// ================= PART 6: MULTI-LEVEL HANDBOOK, 52 ABBREVIATIONS & BOOTSTRAP =================

const HANDBOOK_TABS = [
  {
    "id": 0,
    "title": "1. Kiến Trúc Memory Stack & Ea",
    "subTabs": [
      {
        "title": "1.1 Tổng Quan 5 Tầng",
        "html": "<div class=\"hb-card\"><h3>Vai Trò Của Ea (ModuleId = 40) Trong AUTOSAR Classic</h3><p><b>Ea (EEPROM Abstraction)</b> nằm tại tầng <b>ECU Abstraction (04_ECU_Abstraction)</b>. Nhiệm vụ cốt lõi là cung cấp cơ chế đánh địa chỉ 32-bit ảo hóa không gian <b>Logical Block (BlockNumber)</b> bất biến cho tầng trên (<b>MemIf / NvM</b>), che giấu hoàn toàn sự thay đổi địa chỉ vật lý trên chip <b>EEPROM (SPI/I2C)</b> bên dưới.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 265\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Kiến Trúc Memory Stack 5 Tầng\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Kiến Trúc Memory Stack 5 Tầng AUTOSAR Classic (ModuleId = 40)</text>\n  <rect x=\"25\" y=\"30\" width=\"145\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"30\" data-box-w=\"145\" data-box-h=\"44\"/>\n  <text x=\"97.5\" y=\"49.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">SWC_App / SWC_Diag</text>\n  <text x=\"97.5\" y=\"63.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Rte_Call_NvMService()</text>\n  <rect x=\"210\" y=\"30\" width=\"145\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"210\" data-box-y=\"30\" data-box-w=\"145\" data-box-h=\"44\"/>\n  <text x=\"282.5\" y=\"49.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">RTE Layer</text>\n  <text x=\"282.5\" y=\"63.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Port Client-Server Map</text>\n  <rect x=\"420\" y=\"30\" width=\"155\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"420\" data-box-y=\"30\" data-box-w=\"155\" data-box-h=\"44\"/>\n  <text x=\"497.5\" y=\"49.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">EcuM / BswM</text>\n  <text x=\"497.5\" y=\"63.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ea_Init() &amp; SetMode()</text>\n  <rect x=\"610\" y=\"30\" width=\"145\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"610\" data-box-y=\"30\" data-box-w=\"145\" data-box-h=\"44\"/>\n  <text x=\"682.5\" y=\"49.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">SchM / OS (5ms)</text>\n  <text x=\"682.5\" y=\"63.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ea_MainFunction()</text>\n  <rect x=\"25\" y=\"118\" width=\"155\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"118\" data-box-w=\"155\" data-box-h=\"50\"/>\n  <text x=\"102.5\" y=\"140.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">NvM (Memory Service)</text>\n  <text x=\"102.5\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Queue, CRC, Dataset Index</text>\n  <rect x=\"225\" y=\"118\" width=\"155\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"225\" data-box-y=\"118\" data-box-w=\"155\" data-box-h=\"50\"/>\n  <text x=\"302.5\" y=\"140.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MemIf (Mem Abstraction)</text>\n  <text x=\"302.5\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Route theo DeviceIndex</text>\n  <rect x=\"425\" y=\"118\" width=\"170\" height=\"50\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--pri)\" stroke-width=\"2.2\" data-box-x=\"425\" data-box-y=\"118\" data-box-w=\"170\" data-box-h=\"50\"/>\n  <text x=\"510.0\" y=\"140.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"var(--pri)\">Ea (EEPROM Abst. #40)</text>\n  <text x=\"510.0\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.2\" font-weight=\"600\" fill=\"var(--mut)\">Addr Map, VP Pad, Hdr/Ftr</text>\n  <rect x=\"635\" y=\"118\" width=\"120\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"635\" data-box-y=\"118\" data-box-w=\"120\" data-box-h=\"50\"/>\n  <text x=\"695.0\" y=\"140.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">DET / DEM</text>\n  <text x=\"695.0\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Dev/Runtime &amp; HW</text>\n  <rect x=\"425\" y=\"206\" width=\"170\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"425\" data-box-y=\"206\" data-box-w=\"170\" data-box-h=\"44\"/>\n  <text x=\"510.0\" y=\"225.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Eep Driver (MCAL #90)</text>\n  <text x=\"510.0\" y=\"239.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Eep_Write/Read/Erase</text>\n  <rect x=\"635\" y=\"206\" width=\"120\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"635\" data-box-y=\"206\" data-box-w=\"120\" data-box-h=\"44\"/>\n  <text x=\"695.0\" y=\"225.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">SPI / Ext EEPROM</text>\n  <text x=\"695.0\" y=\"239.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">AT25640 / 25LC256</text>\n  <line x1=\"170\" y1=\"52\" x2=\"210\" y2=\"52\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <path d=\"M282,74 L282,94 L102,94 L102,118\" fill=\"none\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n  <line x1=\"180\" y1=\"143\" x2=\"225\" y2=\"143\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <line x1=\"380\" y1=\"143\" x2=\"425\" y2=\"143\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <line x1=\"595\" y1=\"143\" x2=\"635\" y2=\"143\" stroke=\"var(--err)\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\" marker-end=\"url(#hbArrErr)\"/>\n  <line x1=\"497\" y1=\"74\" x2=\"497\" y2=\"118\" stroke=\"var(--pur)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrPur)\"/>\n  <path d=\"M682,74 L682,96 L535,96 L535,118\" fill=\"none\" stroke=\"var(--pur)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrPur)\"/>\n  <line x1=\"510\" y1=\"168\" x2=\"510\" y2=\"206\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <line x1=\"595\" y1=\"228\" x2=\"635\" y2=\"228\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <line x1=\"695\" y1=\"206\" x2=\"695\" y2=\"168\" stroke=\"var(--err)\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\" marker-end=\"url(#hbArrErr)\"/>\n  <g class=\"hb-pill\" data-px=\"182.0\" data-py=\"135.5\" data-pw=\"40\" data-ph=\"15\">\n    <rect x=\"182.0\" y=\"135.5\" width=\"40\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--warn)\" stroke-width=\"1\"/>\n    <text x=\"202\" y=\"146.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--warn)\">MemIf</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"383.0\" data-py=\"135.5\" data-pw=\"38\" data-ph=\"15\">\n    <rect x=\"383.0\" y=\"135.5\" width=\"38\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--pri)\" stroke-width=\"1\"/>\n    <text x=\"402\" y=\"146.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--pri)\">Ea_*</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"489.0\" data-py=\"179.5\" data-pw=\"42\" data-ph=\"15\">\n    <rect x=\"489.0\" y=\"179.5\" width=\"42\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"510\" y=\"190.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">Eep_*</text>\n  </g>\n</svg></div><div class=\"hb-card\"><h3>Nguyên Tắc Tách Biệt Trong Memory Stack</h3><ul><li><b>SWC &amp; Application:</b> Chỉ gọi <code>Rte_Call_NvMService_*()</code>, tuyệt đối không biết Block nằm ở EEPROM hay Data Flash.</li><li><b>NvM:</b> Lo hàng đợi Immediate/Standard, CRC, Retry, ROM Fallback và Dataset Index.</li><li><b>MemIf:</b> Lớp trừu tượng đồng nhất API cho cả <code>Ea</code> và <code>Fee</code>.</li><li><b>Ea:</b> Quản lý tính toàn vẹn Slot (Header/Footer), Wear-Leveling, Virtual Page Alignment và phát Job tới <code>Eep</code>.</li></ul></div>"
      },
      {
        "title": "1.2 Bảng I/O 10 Module",
        "html": "<div class=\"hb-card\"><h3>Luồng Input / Processing / Output Của 10 Module Tương Tác Với Ea</h3><table class=\"tbl\"><thead><tr><th>STT</th><th>Module</th><th>Input Nhận Vào</th><th>Xử Lý Cốt Lõi</th><th>Output Gửi Đi</th></tr></thead><tbody><tr><td>1</td><td><b>SWC_App / Diag</b></td><td>Sự kiện App / UDS 0x2E, Callback RTE</td><td>Chuẩn bị RAM buffer, gọi cổng Client-Server</td><td><code>Rte_Call_NvMService_Write/ReadBlock</code></td></tr><tr><td>2</td><td><b>RTE</b></td><td>Port call từ SWC &amp; NvM Callback</td><td>Ánh xạ Port-Defined BlockId</td><td><code>NvM_WriteBlock()</code> / Runnable trigger</td></tr><tr><td>3</td><td><b>EcuM / BswM</b></td><td>Startup / Shutdown / Mode switch</td><td>Điều phối init driver &amp; FAST/SLOW</td><td><code>Ea_Init(NULL_PTR)</code>, <code>Ea_SetMode()</code></td></tr><tr><td>4</td><td><b>SchM / OS</b></td><td>OS Alarm chu kỳ 5ms (Configurable)</td><td>Kích hoạt Scheduled Function</td><td><code>Ea_MainFunction()</code>, <code>Eep_MainFunction()</code></td></tr><tr><td>5</td><td><b>NvM (ID=20)</b></td><td>Job từ RTE, Callback từ Ea</td><td>Xếp hàng đợi, CRC, ghép Dataset</td><td><code>MemIf_Read/Write/Invalidate/Erase</code></td></tr><tr><td>6</td><td><b>MemIf (ID=22)</b></td><td><code>(DeviceIndex, BlockNumber)</code></td><td>Macro (1 dev) hoặc FctPtr[Idx] (2+ dev)</td><td><code>Ea_Read()</code> / <code>Ea_Write()</code> (khi DevIdx=0)</td></tr><tr><td>7</td><td><b>Ea (ID=40)</b></td><td>API MemIf, Callback/Poll Eep, Tick</td><td>Logical→Physical, Header/Footer, Wear-Level</td><td><code>Eep_Write/Read/Erase()</code>, NvM Cbk</td></tr><tr><td>8</td><td><b>Eep (ID=90)</b></td><td>Physical Address, Buffer, Length</td><td>Đóng khung SPI/I2C theo Slow/Fast Chunk</td><td>Gửi lệnh phần cứng &amp; báo DEM/JobEnd</td></tr><tr><td>9</td><td><b>SPI / EEPROM HW</b></td><td>SPI MOSI/CLK/CS Frames</td><td>Ghi cell EEPROM (từ 3-5ms mỗi page)</td><td>MISO Data / ECC status / Timeout</td></tr><tr><td>10</td><td><b>DET &amp; DEM</b></td><td><code>Det_ReportError</code> / <code>Dem_SetEventStatus</code></td><td>Ghi nhận lỗi phát triển &amp; lỗi HW thực tế</td><td>Lưu DTC/Event, chặn Job sai luật</td></tr></tbody></table></div>"
      },
      {
        "title": "1.3 Định Tuyến MemIf → Ea",
        "html": "<div class=\"hb-card\"><h3>Cách MemIf Phân Nhánh Giữa Ea Và Fee</h3><p><code>MemIf</code> giúp <code>NvM</code> chỉ cần biết cặp <code>(DeviceIndex, BlockNumber)</code>. Giá trị <code>EaIndex</code> trong Container <code>EaGeneral</code> quy định chỉ số DeviceIndex mà Ea phụ trách (mặc định <code>0</code>).</p><svg class=\"hb-svg\" viewBox=\"0 0 780 236\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Cơ chế định tuyến MemIf tới Ea\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Cơ Chế Định Tuyến MemIf → Ea (Single Device Macro vs Dual Device FctPtr)</text>\n  <rect x=\"25\" y=\"80\" width=\"145\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"80\" data-box-w=\"145\" data-box-h=\"58\"/>\n  <text x=\"97.5\" y=\"100.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">NvM Manager</text>\n  <text x=\"97.5\" y=\"113.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">BlockId + DataIndex</text>\n  <text x=\"97.5\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">=&gt; (DeviceIdx, BlkNo)</text>\n  <rect x=\"220\" y=\"80\" width=\"175\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"220\" data-box-y=\"80\" data-box-w=\"175\" data-box-h=\"58\"/>\n  <text x=\"307.5\" y=\"100.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MemIf Dispatcher</text>\n  <text x=\"307.5\" y=\"113.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 Device: Macro Inline</text>\n  <text x=\"307.5\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">2+ Dev: FctPtr Table[Idx]</text>\n  <rect x=\"455\" y=\"36\" width=\"290\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"455\" data-box-y=\"36\" data-box-w=\"290\" data-box-h=\"62\"/>\n  <text x=\"600.0\" y=\"58.0\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--ok)\">DeviceIndex == 0 (EaIndex=0)</text>\n  <text x=\"600.0\" y=\"71.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\" fill=\"var(--txt)\">Ea_Read / Ea_Write / Ea_Invalidate</text>\n  <text x=\"600.0\" y=\"85.0\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Eep Driver -&gt; External SPI EEPROM</text>\n  <rect x=\"455\" y=\"134\" width=\"290\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"455\" data-box-y=\"134\" data-box-w=\"290\" data-box-h=\"62\"/>\n  <text x=\"600.0\" y=\"156.0\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--cyan)\">DeviceIndex == 1 (FeeIndex=1)</text>\n  <text x=\"600.0\" y=\"169.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\" fill=\"var(--txt)\">Fee_Read / Fee_Write / Fee_Invalidate</text>\n  <text x=\"600.0\" y=\"183.0\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Fls Driver -&gt; Internal Data Flash</text>\n  <line x1=\"170\" y1=\"109\" x2=\"220\" y2=\"109\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <path d=\"M395,95 L425,95 L425,67 L455,67\" fill=\"none\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <path d=\"M395,123 L425,123 L425,165 L455,165\" fill=\"none\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n  <g class=\"hb-pill\" data-px=\"178.0\" data-py=\"84.5\" data-pw=\"34\" data-ph=\"15\">\n    <rect x=\"178.0\" y=\"84.5\" width=\"34\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--warn)\" stroke-width=\"1\"/>\n    <text x=\"195\" y=\"95.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--warn)\">Call</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"405.0\" data-py=\"42.5\" data-pw=\"40\" data-ph=\"15\">\n    <rect x=\"405.0\" y=\"42.5\" width=\"40\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"425\" y=\"53.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">Idx=0</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"405.0\" data-py=\"174.5\" data-pw=\"40\" data-ph=\"15\">\n    <rect x=\"405.0\" y=\"174.5\" width=\"40\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--cyan)\" stroke-width=\"1\"/>\n    <text x=\"425\" y=\"185.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--cyan)\">Idx=1</text>\n  </g>\n  <text x=\"390\" y=\"220\" text-anchor=\"middle\" font-size=\"9.8\" font-weight=\"600\" fill=\"var(--mut)\">Lưu ý: Khi hệ thống chỉ dùng 1 thiết bị EEPROM, MemIf biên dịch thành #define trực tiếp sang Ea_* (0 byte RAM overhead).</text>\n</svg></div><div class=\"hb-card\"><h3>Macro Mode vs Function Pointer Array</h3><table class=\"tbl\"><thead><tr><th>Chế độ MemIf</th><th>Điều kiện cấu hình</th><th>Cơ chế gọi hàm</th><th>Chi phí RAM/Flash</th></tr></thead><tbody><tr><td><b>1 Device (Only Ea)</b></td><td><code>MemIfNumberOfDevices == 1</code></td><td>Macro <code>#define MemIf_Write(dev,blk,ptr) Ea_Write(blk,ptr)</code></td><td>0 byte Flash table, tốc độ tối đa</td></tr><tr><td><b>2+ Devices (Ea + Fee)</b></td><td><code>MemIfNumberOfDevices &gt;= 2</code></td><td>Bảng con trỏ hàm <code>MemIf_WriteFctPtr[DeviceIndex](blk,ptr)</code></td><td>Tốn nhẹ ROM bảng lookup, linh hoạt hybrid</td></tr></tbody></table></div>"
      },
      {
        "title": "1.4 Hai Thanh Ghi 8-Bit",
        "html": "<div class=\"hb-card\"><h3>Giải Mã Dual 8-Bit Monitor Trong Simulator</h3><p>Simulator nén toàn bộ trạng thái nội tại của Ea thành 2 thanh ghi 8-bit tương tác trực tiếp, giúp quan sát ngay lập tức mỗi biến đổi bit sau từng <code>+5ms MainFn</code> hoặc mỗi lần tiêm lỗi.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 254\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Cấu trúc 2 thanh ghi 8-bit\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Cấu Trúc 2 Thanh Ghi 8-Bit Trực Quan Trong Simulator</text>\n  <text x=\"25\" y=\"42\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\" fill=\"var(--pri)\">Reg A: Ea_ModuleJobStatusByte (Trạng thái Module &amp; Chế độ)</text>\n  <rect x=\"25\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"67.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b7 INIT</text>\n  <text x=\"67.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"117\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"117\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"159.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b6 BUSY</text>\n  <text x=\"159.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"209\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"209\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"251.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b5 B_INT</text>\n  <text x=\"251.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"301\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"301\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"343.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b4 PEND</text>\n  <text x=\"343.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"393\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"393\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"435.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b3 OK</text>\n  <text x=\"435.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"485\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"485\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"527.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b2 EEP</text>\n  <text x=\"527.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"577\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"577\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"619.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b1 FAST</text>\n  <text x=\"619.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"669\" y=\"50\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"669\" data-box-y=\"50\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"711.0\" y=\"68.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b0 POLL</text>\n  <text x=\"711.0\" y=\"82.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <text x=\"25\" y=\"122\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\" fill=\"var(--cyan)\">Reg B: Ea_BlockHeaderControlByte (Cờ Block đang chọn &amp; Toàn vẹn)</text>\n  <rect x=\"25\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"67.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b7 0xA5</text>\n  <text x=\"67.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"117\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"117\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"159.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b6 0x5A</text>\n  <text x=\"159.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"209\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"209\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"251.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b5 INC</text>\n  <text x=\"251.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"301\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"301\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"343.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b4 INV</text>\n  <text x=\"343.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"393\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"393\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"435.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b3 IMM</text>\n  <text x=\"435.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"485\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"485\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"527.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b2 ERS</text>\n  <text x=\"527.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"577\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"577\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"619.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b1 WEAR</text>\n  <text x=\"619.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"669\" y=\"130\" width=\"84\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"669\" data-box-y=\"130\" data-box-w=\"84\" data-box-h=\"42\"/>\n  <text x=\"711.0\" y=\"148.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">b0 ERR</text>\n  <text x=\"711.0\" y=\"162.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">1 / 0</text>\n  <rect x=\"25\" y=\"192\" width=\"728\" height=\"48\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"192\" data-box-w=\"728\" data-box-h=\"48\"/>\n  <text x=\"389.0\" y=\"213.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Click bất kỳ ô bit nào trên Bảng Monitor (Dual 8-Bit Registers)</text>\n  <text x=\"389.0\" y=\"227.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">để bật/tắt EaInitialized, SetMode(FAST/SLOW), Polling, Immediate hoặc tiêm/gỡ lỗi Footer!</text>\n</svg></div><div class=\"hb-card\"><h3>Chi Tiết Từng Bit & Tương Tác Click-To-Toggle</h3><table class=\"tbl\"><thead><tr><th>Bit</th><th>Reg A: Ea_ModuleJobStatusByte</th><th>Reg B: Ea_BlockHeaderControlByte</th></tr></thead><tbody><tr><td><b>b7</b></td><td><code>EA_INITIALIZED</code> (1=Init xong, 0=UNINIT)</td><td><code>BLK_HDR_START_WR</code> (1 khi Header[0]==0xA5)</td></tr><tr><td><b>b6</b></td><td><code>EA_STATUS_BUSY</code> (1=MEMIF_BUSY)</td><td><code>BLK_FTR_VALID</code> (1 khi Footer[0]==0x5A khớp Cnt)</td></tr><tr><td><b>b5</b></td><td><code>EA_BUSY_INTERNAL</code> (1 khi Init quét Slot)</td><td><code>BLK_INCONSISTENT</code> (1 khi mất nguồn / 0xFF rỗng)</td></tr><tr><td><b>b4</b></td><td><code>JOB_PENDING</code> (1 khi Job chưa xong)</td><td><code>BLK_INVALIDATED</code> (1 khi Header==0x0000)</td></tr><tr><td><b>b3</b></td><td><code>JOB_RESULT_OK</code> (1 khi hoàn tất OK)</td><td><code>IMM_DATA_BLOCK</code> (1 khi EaImmediateData=TRUE)</td></tr><tr><td><b>b2</b></td><td><code>EEP_SUBJOB_ACTV</code> (1 khi chờ Eep_MainFunction)</td><td><code>IMM_PRE_ERASED</code> (1 khi đã gọi EraseImmediate)</td></tr><tr><td><b>b1</b></td><td><code>FAST_MODE_EN</code> (1=FAST, 0=SLOW)</td><td><code>WEAR_SLOT_ROTATE</code> (1 khi Block có &gt;1 Slot)</td></tr><tr><td><b>b0</b></td><td><code>POLLING_MODE_EN</code> (1=Polling, 0=Callback)</td><td><code>JOB_ERR_OR_CANCEL</code> (1 khi Cancel/HW Err/DET)</td></tr></tbody></table></div>"
      }
    ]
  },
  {
    "id": 1,
    "title": "2. Ánh Xạ, Virtual Page & Wear-Level",
    "subTabs": [
      {
        "title": "2.1 Công Thức BlockNumber",
        "html": "<div class=\"hb-card\"><h3>Cách NvM Tạo EaBlockNumber Từ BlockBase & DataIndex</h3><p>Trong AUTOSAR, một <code>NvMBlockDescriptor</code> kiểu <code>NVM_BLOCK_DATASET</code> có thể chứa nhiều bản sao dữ liệu cùng cấu trúc (ví dụ Key/VIN/Chẩn đoán). Khi truyền xuống Ea, NvM mã hóa <b>BlockBase</b> và <b>DataIndex</b> thành <b>EaBlockNumber</b> duy nhất theo chuẩn <code>SWS_Ea</code>:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 202\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Công thức EaBlockNumber và bảng Block\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Ánh Xạ Đa Tầng: NvM (Base, DataIndex) → EaBlockNumber → EEPROM Slot Address</text>\n  <rect x=\"25\" y=\"42\" width=\"175\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"175\" data-box-h=\"58\"/>\n  <text x=\"112.5\" y=\"62.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">NvM Configuration</text>\n  <text x=\"112.5\" y=\"75.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">NvMDatasetSelectionBits=2</text>\n  <text x=\"112.5\" y=\"89.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">BaseBlk=2, DataIndex=0/1</text>\n  <rect x=\"250\" y=\"42\" width=\"225\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"250\" data-box-y=\"42\" data-box-w=\"225\" data-box-h=\"58\"/>\n  <text x=\"362.5\" y=\"62.0\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--pri)\">Công Thức Bitwise SWS_Ea</text>\n  <text x=\"362.5\" y=\"75.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"var(--cyan)\">BlkNo = (Base &lt;&lt; k) | DataIdx</text>\n  <text x=\"362.5\" y=\"89.0\" text-anchor=\"middle\" font-size=\"9.2\" font-weight=\"500\" fill=\"var(--mut)\">Simulator: Blk #2 [DS 0], Blk #3 [DS 1]</text>\n  <rect x=\"525\" y=\"42\" width=\"230\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"525\" data-box-y=\"42\" data-box-w=\"230\" data-box-h=\"58\"/>\n  <text x=\"640.0\" y=\"62.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">EaBlockConfiguration</text>\n  <text x=\"640.0\" y=\"75.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk #2 -&gt; 0x0010 (16B)</text>\n  <text x=\"640.0\" y=\"89.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk #3 -&gt; 0x0020 (16B)</text>\n  <line x1=\"200\" y1=\"71\" x2=\"250\" y2=\"71\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <line x1=\"475\" y1=\"71\" x2=\"525\" y2=\"71\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <g class=\"hb-pill\" data-px=\"206.0\" data-py=\"44.5\" data-pw=\"38\" data-ph=\"15\">\n    <rect x=\"206.0\" y=\"44.5\" width=\"38\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--warn)\" stroke-width=\"1\"/>\n    <text x=\"225\" y=\"55.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--warn)\">Input</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"482.0\" data-py=\"44.5\" data-pw=\"36\" data-ph=\"15\">\n    <rect x=\"482.0\" y=\"44.5\" width=\"36\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"500\" y=\"55.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">Map</text>\n  </g>\n  <rect x=\"25\" y=\"128\" width=\"165\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"128\" data-box-w=\"165\" data-box-h=\"56\"/>\n  <text x=\"107.5\" y=\"147.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Blk #1 (Calib)</text>\n  <text x=\"107.5\" y=\"160.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">12B + 4B OH = 16B</text>\n  <text x=\"107.5\" y=\"174.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Slot #0 @ 0x0000</text>\n  <rect x=\"205\" y=\"128\" width=\"175\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"205\" data-box-y=\"128\" data-box-w=\"175\" data-box-h=\"56\"/>\n  <text x=\"292.5\" y=\"147.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Blk #2 / #3 (Dataset)</text>\n  <text x=\"292.5\" y=\"160.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">8B+4B+4B Pad = 16B mỗi copy</text>\n  <text x=\"292.5\" y=\"174.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">@ 0x0010 &amp; 0x0020</text>\n  <rect x=\"395\" y=\"128\" width=\"185\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"395\" data-box-y=\"128\" data-box-w=\"185\" data-box-h=\"56\"/>\n  <text x=\"487.5\" y=\"147.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Blk #4 (Odometer Wear)</text>\n  <text x=\"487.5\" y=\"160.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">400k cycles -&gt; 4 Slots × 8B</text>\n  <text x=\"487.5\" y=\"174.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">@ 0x0030..0x004F (32B)</text>\n  <rect x=\"595\" y=\"128\" width=\"160\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"595\" data-box-y=\"128\" data-box-w=\"160\" data-box-h=\"56\"/>\n  <text x=\"675.0\" y=\"147.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Blk #5 (Crash Imm)</text>\n  <text x=\"675.0\" y=\"160.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">ImmediateData=TRUE</text>\n  <text x=\"675.0\" y=\"174.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">10B+4B+2B Pad = 16B</text>\n</svg></div><div class=\"hb-card\"><h3>4 Block Mẫu Trong Simulator</h3><table class=\"tbl\"><thead><tr><th>Logical Entry</th><th>BlockNumber</th><th>Payload Size</th><th>Thuộc Tính Chính</th><th>Mục Đích Thực Tế</th></tr></thead><tbody><tr><td><b>Blk_Calibration (BLK1)</b></td><td><code>#1 (0x0001)</code></td><td>12 B → 16 B</td><td>Single Slot · Immediate=FALSE</td><td>Tham số hiệu chỉnh chuẩn</td></tr><tr><td><b>Blk_Dataset[0/1]</b></td><td><code>#2, #3</code></td><td>8 B → 16 B</td><td>Base=2 · Dataset Copy 0 &amp; 1</td><td>2 phiên bản VIN / Certificate</td></tr><tr><td><b>Blk_Odometer_Wear</b></td><td><code>#4 (0x0004)</code></td><td>4 B → 8 B × 4</td><td>WriteCycles=400k → 4 Slots</td><td>Ghi quãng đường liên tục</td></tr><tr><td><b>Blk_Crash_ImmData</b></td><td><code>#5 (0x0005)</code></td><td>10 B → 16 B</td><td>ImmediateData=TRUE</td><td>Dữ liệu túi khí va chạm</td></tr></tbody></table></div>"
      },
      {
        "title": "2.2 Virtual Page & Padding",
        "html": "<div class=\"hb-card\"><h3>Căn Chỉnh Địa Chỉ Vật Lý Theo EaVirtualPageSize</h3><p>Để tương thích với độ rộng trang ghi (Page Size) của phần cứng EEPROM (4B, 8B, 16B hoặc 32B) và đảm bảo hai block kề nhau không bao giờ ghi đè chung một trang EEPROM vật lý, Ea luôn làm tròn kích thước mỗi Slot lên bội số của <code>EaVirtualPageSize</code>.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 222\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Căn chỉnh Virtual Page Size\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Căn Chỉnh Trang Ảo (EaVirtualPageSize = 8B vs 4B) &amp; Padding 0xFF</text>\n  <text x=\"25\" y=\"44\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\" fill=\"var(--pri)\">Công thức: SlotSize = Ceil((DataSize + EaBlockOverhead) / VirtualPage) × VirtualPage</text>\n  <text x=\"25\" y=\"74\" text-anchor=\"start\" font-size=\"9.5\" font-weight=\"600\" fill=\"var(--txt)\">Trường hợp A: Blk #1 (12B Data + 4B OH = 16B) với VP = 8B -&gt; Vừa khít (Pad = 0B)</text>\n  <rect x=\"25\" y=\"84\" width=\"95\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"84\" data-box-w=\"95\" data-box-h=\"40\"/>\n  <text x=\"72.5\" y=\"101.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Hdr (2B)</text>\n  <text x=\"72.5\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0xA5 Cnt</text>\n  <rect x=\"125\" y=\"84\" width=\"240\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"125\" data-box-y=\"84\" data-box-w=\"240\" data-box-h=\"40\"/>\n  <text x=\"245.0\" y=\"101.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Data Payload (12B)</text>\n  <text x=\"245.0\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">User RAM Data</text>\n  <rect x=\"370\" y=\"84\" width=\"95\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"370\" data-box-y=\"84\" data-box-w=\"95\" data-box-h=\"40\"/>\n  <text x=\"417.5\" y=\"101.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ftr (2B)</text>\n  <text x=\"417.5\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x5A Cnt</text>\n  <rect x=\"475\" y=\"84\" width=\"270\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"475\" data-box-y=\"84\" data-box-w=\"270\" data-box-h=\"40\"/>\n  <text x=\"610.0\" y=\"101.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tổng = 16B = 2 × 8B</text>\n  <text x=\"610.0\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Không dư Padding</text>\n  <text x=\"25\" y=\"152\" text-anchor=\"start\" font-size=\"9.5\" font-weight=\"600\" fill=\"var(--warn)\">Trường hợp B: Blk #3 (4B Data + 4B OH = 8B) nếu đổi VP = 16B -&gt; Tốn 8B Padding 0xFF</text>\n  <rect x=\"25\" y=\"162\" width=\"85\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"162\" data-box-w=\"85\" data-box-h=\"40\"/>\n  <text x=\"67.5\" y=\"179.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Hdr (2B)</text>\n  <text x=\"67.5\" y=\"193.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0xA5</text>\n  <rect x=\"115\" y=\"162\" width=\"130\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"115\" data-box-y=\"162\" data-box-w=\"130\" data-box-h=\"40\"/>\n  <text x=\"180.0\" y=\"179.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Data (4B)</text>\n  <text x=\"180.0\" y=\"193.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Odometer</text>\n  <rect x=\"250\" y=\"162\" width=\"85\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"250\" data-box-y=\"162\" data-box-w=\"85\" data-box-h=\"40\"/>\n  <text x=\"292.5\" y=\"179.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ftr (2B)</text>\n  <text x=\"292.5\" y=\"193.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x5A</text>\n  <rect x=\"340\" y=\"162\" width=\"165\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"340\" data-box-y=\"162\" data-box-w=\"165\" data-box-h=\"40\"/>\n  <text x=\"422.5\" y=\"179.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">VP Pad (8B = 0xFF)</text>\n  <text x=\"422.5\" y=\"193.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Chừa trống canh VP=16</text>\n  <rect x=\"515\" y=\"162\" width=\"230\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"515\" data-box-y=\"162\" data-box-w=\"230\" data-box-h=\"40\"/>\n  <text x=\"630.0\" y=\"179.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tổng = 16B/Slot × 4 Slots</text>\n  <text x=\"630.0\" y=\"193.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Chiếm 64B EEPROM</text>\n</svg></div><div class=\"hb-card\"><h3>Công Thức Tính Toán Kích Thước Thực Tế</h3><ul><li><code>RawSize = EaBlockSize + EaBlockOverhead</code> (mặc định Overhead = 4B cho 2B Header + 2B Footer).</li><li><code>AlignedSlotSize = Math.ceil(RawSize / EaVirtualPageSize) * EaVirtualPageSize</code>.</li><li><code>PaddingBytes = AlignedSlotSize - RawSize</code> (được giữ ở giá trị erased <code>0xFF</code>).</li><li><b>Trade-off:</b> Tăng <code>EaVirtualPageSize</code> từ 8B lên 16B sẽ làm mỗi block tốn thêm Padding <code>0xFF</code> và tăng tổng dung lượng EEPROM tiêu thụ! Hãy thử điều chỉnh ở Tab 0 hoặc What-If trong Kịch bản <b>S1/S5</b>.</li></ul></div>"
      },
      {
        "title": "2.3 Multi-Slot Wear-Leveling",
        "html": "<div class=\"hb-card\"><h3>Thuật Toán Xoay Vòng Slot Chống Chai Mòn EEPROM</h3><p>Mỗi cell EEPROM chỉ chịu được tối đa <code>EepAllowedWriteCycles</code> (ví dụ <code>100,000</code> lần). Nếu một Block như Odometer cần <code>EaNumberOfWriteCycles = 400,000</code> lần trong vòng đời xe, Ea tự động cấp phát <code>Math.ceil(400000 / 100000) = 4 Slots</code> liền kề và xoay vòng luân phiên mỗi lần <code>Ea_Write()</code>.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 208\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Multi-Slot Wear-Leveling Rotation\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Cơ Chế Multi-Slot Wear-Leveling Cho Blk #3 (400k Cycles / 100k = 4 Slots)</text>\n  <rect x=\"25\" y=\"42\" width=\"162\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--mut)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"162\" data-box-h=\"62\"/>\n  <text x=\"106.0\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Slot #0 @ 0x0030</text>\n  <text x=\"106.0\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cnt=0x01 (Old)</text>\n  <text x=\"106.0\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cycles: 1</text>\n  <line x1=\"187\" y1=\"73\" x2=\"213\" y2=\"73\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"213\" y=\"42\" width=\"162\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--mut)\" stroke-width=\"1.5\" data-box-x=\"213\" data-box-y=\"42\" data-box-w=\"162\" data-box-h=\"62\"/>\n  <text x=\"294.0\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Slot #1 @ 0x0038</text>\n  <text x=\"294.0\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cnt=0x02 (Old)</text>\n  <text x=\"294.0\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cycles: 2</text>\n  <line x1=\"375\" y1=\"73\" x2=\"401\" y2=\"73\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"401\" y=\"42\" width=\"162\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"2.2\" data-box-x=\"401\" data-box-y=\"42\" data-box-w=\"162\" data-box-h=\"62\"/>\n  <text x=\"482.0\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Slot #2 @ 0x0040</text>\n  <text x=\"482.0\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cnt=0x03 ACTIVE</text>\n  <text x=\"482.0\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Newest Valid!</text>\n  <line x1=\"563\" y1=\"73\" x2=\"589\" y2=\"73\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"589\" y=\"42\" width=\"162\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"589\" data-box-y=\"42\" data-box-w=\"162\" data-box-h=\"62\"/>\n  <text x=\"670.0\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Slot #3 @ 0x0048</text>\n  <text x=\"670.0\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0xFF (Next Write)</text>\n  <text x=\"670.0\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cycles: 0</text>\n  <rect x=\"25\" y=\"134\" width=\"345\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"134\" data-box-w=\"345\" data-box-h=\"58\"/>\n  <text x=\"197.5\" y=\"154.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Lần Ea_Write(3) kế tiếp:</text>\n  <text x=\"197.5\" y=\"167.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Tự động xoay (2 + 1) % 4 → Chọn Slot #3!</text>\n  <text x=\"197.5\" y=\"181.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Tăng SeqCounter = 0x04 chống mài mòn 1 ô.</text>\n  <rect x=\"400\" y=\"134\" width=\"355\" height=\"58\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"400\" data-box-y=\"134\" data-box-w=\"355\" data-box-h=\"58\"/>\n  <text x=\"577.5\" y=\"154.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Xử lý Wrap-Around 8-Bit Counter (0xFF → 0x00):</text>\n  <text x=\"577.5\" y=\"167.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">So sánh Modulo ((a - b) &amp; 0xFF) &lt; 128:</text>\n  <text x=\"577.5\" y=\"181.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x00 vẫn được nhận diện mới hơn 0xFF!</text>\n  <line x1=\"650\" y1=\"104\" x2=\"650\" y2=\"134\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n  <line x1=\"240\" y1=\"134\" x2=\"460\" y2=\"104\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n</svg></div><div class=\"hb-card\"><h3>Lợi Ích Kép Của Multi-Slot Rotation</h3><ul><li><b>Kéo dài tuổi thọ gấp N lần:</b> Mỗi Slot chỉ phải chịu <code>1/N</code> số chu kỳ xóa-ghi thực tế.</li><li><b>An toàn Rollback tự nhiên:</b> Vì lần ghi mới viết sang Slot kế tiếp (ví dụ từ Slot #2 sang Slot #3), nếu xe sập nguồn đột ngột giữa pha ghi Slot #3, toàn bộ dữ liệu cũ trong <b>Slot #2 vẫn còn nguyên vẹn VALID</b>!</li></ul></div>"
      },
      {
        "title": "2.4 Quét Slot & Wrap-Around",
        "html": "<div class=\"hb-card\"><h3>Thuật Toán Xác Định Bản Ghi Mới Nhất Khi Khởi Động (Counter Rollover)</h3><p>Mỗi Header/Footer mang theo 1-byte <b>Sequence Counter</b> tăng dần sau mỗi lần ghi thành công (<code>0x01 → 0x02 → ... → 0xFE → 0xFF → 0x00</code>). Khi Counter quay vòng từ <code>0xFF</code> sang <code>0x00</code>, nếu so sánh số nguyên thông thường (<code>0x00 &lt; 0xFF</code>) sẽ chọn nhầm bản cũ!</p><table class=\"tbl\"><thead><tr><th>Slot</th><th>Header Cnt</th><th>Footer Cnt</th><th>Trạng Thái Slot</th><th>So Sánh Modulo ((a - b) &amp; 0xFF) &lt; 128</th></tr></thead><tbody><tr><td>Slot #0</td><td><code>0xFE</code></td><td><code>0xFE</code></td><td>VALID</td><td>Cũ hơn <code>0xFF</code></td></tr><tr><td>Slot #1</td><td><code>0xFF</code></td><td><code>0xFF</code></td><td>VALID</td><td>Cũ hơn <code>0x00</code> vì <code>(0x00 - 0xFF) &amp; 0xFF == 1 &lt; 128</code></td></tr><tr><td>Slot #2</td><td><code>0x00</code></td><td><code>0x00</code></td><td><b>VALID (MỚI NHẤT!)</b></td><td>Được Ea chọn làm Active Slot sau Wrap-Around!</td></tr><tr><td>Slot #3</td><td><code>0xFF</code></td><td><code>0xFF</code></td><td>ERASED / INCONSIS</td><td>Bị bỏ qua khi tìm bản Valid mới nhất</td></tr></tbody></table><p style='margin-top:8px'>💡 Trải nghiệm thực tế ở <b>Kịch bản S8</b> để chứng kiến <code>0xFF → 0x00</code> hoạt động chính xác như thế nào!</p></div>"
      }
    ]
  },
  {
    "id": 2,
    "title": "3. Header/Footer & Chống Sập Nguồn",
    "subTabs": [
      {
        "title": "3.1 Giải Phẫu 1 Slot EEPROM",
        "html": "<div class=\"hb-card\"><h3>Định Dạng Vật Lý Của Một Block Slot Trong Ea</h3><p>Thay vì lưu dữ liệu thô dễ hỏng khi mất điện, Ea bọc mỗi bản ghi giữa <b>Start Marker (Header)</b> ở đầu và <b>Valid Marker (Footer)</b> ở cuối. Chính khoảng cách hai đầu này giúp phát hiện chính xác việc ghi bị ngắt quãng ở bất kỳ byte nào ở giữa.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 204\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Giải phẫu cấu trúc Header/Footer Slot\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Cấu Trúc Byte-Level Của 1 Slot Vật Lý Trong EEPROM</text>\n  <rect x=\"25\" y=\"42\" width=\"155\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"155\" data-box-h=\"62\"/>\n  <text x=\"102.5\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Header (2 Bytes)</text>\n  <text x=\"102.5\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Byte[0] = 0xA5 (Start)</text>\n  <text x=\"102.5\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Byte[1] = SeqCnt</text>\n  <rect x=\"195\" y=\"42\" width=\"235\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"195\" data-box-y=\"42\" data-box-w=\"235\" data-box-h=\"62\"/>\n  <text x=\"312.5\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Data Payload (N Bytes)</text>\n  <text x=\"312.5\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Dữ liệu người dùng từ NvM</text>\n  <text x=\"312.5\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ghi sau khi đã ghi Header</text>\n  <rect x=\"445\" y=\"42\" width=\"165\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"445\" data-box-y=\"42\" data-box-w=\"165\" data-box-h=\"62\"/>\n  <text x=\"527.5\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Footer (2 Bytes)</text>\n  <text x=\"527.5\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Byte[N+2] = 0x5A (End)</text>\n  <text x=\"527.5\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Byte[N+3] = SeqCnt</text>\n  <rect x=\"625\" y=\"42\" width=\"130\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--mut)\" stroke-width=\"1.5\" data-box-x=\"625\" data-box-y=\"42\" data-box-w=\"130\" data-box-h=\"62\"/>\n  <text x=\"690.0\" y=\"64.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Padding (0..VP-1)</text>\n  <text x=\"690.0\" y=\"77.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Giá trị 0xFF</text>\n  <text x=\"690.0\" y=\"91.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Canh biên VirtualPage</text>\n  <line x1=\"180\" y1=\"73\" x2=\"195\" y2=\"73\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <line x1=\"430\" y1=\"73\" x2=\"445\" y2=\"73\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n  <line x1=\"610\" y1=\"73\" x2=\"625\" y2=\"73\" stroke=\"var(--mut)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"25\" y=\"130\" width=\"175\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"130\" data-box-w=\"175\" data-box-h=\"56\"/>\n  <text x=\"112.5\" y=\"149.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">VALID</text>\n  <text x=\"112.5\" y=\"162.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Hdr=0xA5 &amp; Ftr=0x5A</text>\n  <text x=\"112.5\" y=\"176.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Cnt(Hdr) == Cnt(Ftr)</text>\n  <rect x=\"215\" y=\"130\" width=\"180\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"215\" data-box-y=\"130\" data-box-w=\"180\" data-box-h=\"56\"/>\n  <text x=\"305.0\" y=\"149.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">INCONSISTENT</text>\n  <text x=\"305.0\" y=\"162.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Hdr=0xA5 &amp; Ftr=0xFF</text>\n  <text x=\"305.0\" y=\"176.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Mất nguồn giữa chừng</text>\n  <rect x=\"410\" y=\"130\" width=\"170\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"410\" data-box-y=\"130\" data-box-w=\"170\" data-box-h=\"56\"/>\n  <text x=\"495.0\" y=\"149.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">INVALID</text>\n  <text x=\"495.0\" y=\"162.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Hdr=0x00 &amp; Ftr=0x00</text>\n  <text x=\"495.0\" y=\"176.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Sau Ea_InvalidateBlock</text>\n  <rect x=\"595\" y=\"130\" width=\"160\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"595\" data-box-y=\"130\" data-box-w=\"160\" data-box-h=\"56\"/>\n  <text x=\"675.0\" y=\"149.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">ERASED / PRE_ERS</text>\n  <text x=\"675.0\" y=\"162.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Toàn bộ byte = 0xFF</text>\n  <text x=\"675.0\" y=\"176.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Sau EraseImmediate</text>\n</svg></div><div class=\"hb-card\"><h3>Ý Nghĩa Các Giá Trị Byte Đặc Biệt</h3><table class=\"tbl\"><thead><tr><th>Byte Pattern</th><th>Vị Trí</th><th>Ý Nghĩa Kỹ Thuật</th></tr></thead><tbody><tr><td><code>0xA5, Cnt</code></td><td>Header (2B đầu)</td><td>Bắt đầu phiên ghi thứ <code>Cnt</code></td></tr><tr><td><code>0x5A, Cnt</code></td><td>Footer (2B sau Data)</td><td>Xác nhận Payload + Padding ghi hoàn tất nguyên vẹn</td></tr><tr><td><code>0x00, 0x00</code></td><td>Header &amp; Footer</td><td>Block đã bị <code>Ea_InvalidateBlock()</code> vô hiệu hóa chủ động</td></tr><tr><td><code>0xFF, 0xFF</code></td><td>Toàn vùng / Footer</td><td>Ô nhớ trắng mới xóa (Erased) hoặc Footer chưa kịp ghi khi mất điện</td></tr></tbody></table></div>"
      },
      {
        "title": "3.2 Ghi 3 Pha & Power-Loss",
        "html": "<div class=\"hb-card\"><h3>Chuỗi Ghi Nguyên Tử (Atomic Commit) 3 Bước Trong Ea_MainFunction()</h3><p>Một lệnh <code>Ea_Write()</code> không bao giờ ghi 1 mạch vô điều kiện. Nó chia làm 3 sub-job tuần tự thông qua <code>Eep_Write()</code>:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 210\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Chu trình 3 pha và chống sập nguồn\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Chu Trình Ghi 3 Pha Chống Sập Nguồn &amp; Kịch Bản Power-Loss Mid-Write</text>\n  <rect x=\"25\" y=\"38\" width=\"175\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"38\" data-box-w=\"175\" data-box-h=\"54\"/>\n  <text x=\"112.5\" y=\"56.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Pha 1: WRITE_HDR</text>\n  <text x=\"112.5\" y=\"69.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Eep_Write(0xA5, Cnt)</text>\n  <text x=\"112.5\" y=\"83.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Đánh dấu bắt đầu ghi</text>\n  <rect x=\"245\" y=\"38\" width=\"210\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"245\" data-box-y=\"38\" data-box-w=\"210\" data-box-h=\"54\"/>\n  <text x=\"350.0\" y=\"56.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Pha 2: WRITE_DATA</text>\n  <text x=\"350.0\" y=\"69.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Eep_Write(Payload N bytes)</text>\n  <text x=\"350.0\" y=\"83.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ghi dữ liệu vào phần thân</text>\n  <rect x=\"505\" y=\"38\" width=\"240\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"505\" data-box-y=\"38\" data-box-w=\"240\" data-box-h=\"54\"/>\n  <text x=\"625.0\" y=\"56.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Pha 3: WRITE_FTR (Commit)</text>\n  <text x=\"625.0\" y=\"69.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Eep_Write(0x5A, Cnt) -&gt; VALID</text>\n  <text x=\"625.0\" y=\"83.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gọi NvM_JobEndNotification()</text>\n  <line x1=\"200\" y1=\"65\" x2=\"245\" y2=\"65\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <line x1=\"455\" y1=\"65\" x2=\"505\" y2=\"65\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n  <g class=\"hb-pill\" data-px=\"211.0\" data-py=\"40.5\" data-pw=\"22\" data-ph=\"15\">\n    <rect x=\"211.0\" y=\"40.5\" width=\"22\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--pri)\" stroke-width=\"1\"/>\n    <text x=\"222\" y=\"51.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--pri)\">1</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"469.0\" data-py=\"40.5\" data-pw=\"22\" data-ph=\"15\">\n    <rect x=\"469.0\" y=\"40.5\" width=\"22\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--cyan)\" stroke-width=\"1\"/>\n    <text x=\"480\" y=\"51.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--cyan)\">2</text>\n  </g>\n  <rect x=\"210\" y=\"128\" width=\"280\" height=\"64\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"2\" data-box-x=\"210\" data-box-y=\"128\" data-box-w=\"280\" data-box-h=\"64\"/>\n  <text x=\"350.0\" y=\"151.0\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--err)\">SẬP NGUỒN GIỮA PHA 2!</text>\n  <text x=\"350.0\" y=\"164.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\" fill=\"var(--txt)\">Footer vẫn là 0xFF (chưa tới Pha 3)</text>\n  <text x=\"350.0\" y=\"178.0\" text-anchor=\"middle\" font-size=\"9.2\" font-weight=\"500\" fill=\"var(--mut)\">Lần bật máy sau: Ea_Read trả MEMIF_BLOCK_INCONSISTENT</text>\n  <rect x=\"525\" y=\"128\" width=\"220\" height=\"64\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"525\" data-box-y=\"128\" data-box-w=\"220\" data-box-h=\"64\"/>\n  <text x=\"635.0\" y=\"151.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Bảo Toàn Hệ Thống:</text>\n  <text x=\"635.0\" y=\"164.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">• Wear-Slot cũ (Slot #2) còn nguyên!</text>\n  <text x=\"635.0\" y=\"178.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">• Hoặc NvM dùng ROM Default Data.</text>\n  <line x1=\"350\" y1=\"92\" x2=\"350\" y2=\"128\" stroke=\"var(--err)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrErr)\"/>\n  <line x1=\"490\" y1=\"160\" x2=\"525\" y2=\"160\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <g class=\"hb-pill\" data-px=\"313.0\" data-py=\"102.5\" data-pw=\"74\" data-ph=\"15\">\n    <rect x=\"313.0\" y=\"102.5\" width=\"74\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--err)\" stroke-width=\"1\"/>\n    <text x=\"350\" y=\"113.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--err)\">Power Loss!</text>\n  </g>\n</svg></div><div class=\"hb-card\"><h3>Điều Gì Xảy Ra Nếu Bật SimulatePowerLossMidWrite = TRUE?</h3><ul><li><b>Pha 1 xong:</b> Header đã xuống EEPROM là <code>[0xA5, Cnt]</code>.</li><li><b>Pha 2 bị ngắt giữa chừng:</b> Chỉ một nửa Payload được ghi, Pha 3 (<code>WRITE_FTR</code>) không bao giờ được thực thi nên Footer vẫn giữ <code>0xFF, 0xFF</code>.</li><li><b>Kết quả đọc lại:</b> Khi gọi <code>Ea_Read()</code>, Ea thấy <code>Hdr=0xA5</code> nhưng <code>Ftr!=0x5A</code> → kết luận ngay <b><code>MEMIF_BLOCK_INCONSISTENT</code></b> để ngăn SWC dùng dữ liệu nửa vời bị rác!</li></ul></div>"
      },
      {
        "title": "3.3 Cây Quyết Định Ea_Read",
        "html": "<div class=\"hb-card\"><h3>Cách Ea Phân Loại Kết Quả Đọc Lên NvM (SWS_Ea_00086)</h3><p>Mỗi lần <code>Ea_Read()</code> chạy, Ea không tin tưởng mù quáng vào payload mà kiểm tra cặp Header/Footer trước khi xác nhận kết quả cho <code>NvM</code>:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 236\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Cây quyết định Ea_Read\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Cây Quyết Định Khi Thực Thi Ea_Read() Kiểm Tra Tính Toàn Vẹn</text>\n  <rect x=\"25\" y=\"76\" width=\"155\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"76\" data-box-w=\"155\" data-box-h=\"54\"/>\n  <text x=\"102.5\" y=\"94.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ea_Read(BlkNo)</text>\n  <text x=\"102.5\" y=\"107.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Quét Header (2B)</text>\n  <text x=\"102.5\" y=\"121.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">và Footer (2B)</text>\n  <rect x=\"230\" y=\"32\" width=\"230\" height=\"46\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"230\" data-box-y=\"32\" data-box-w=\"230\" data-box-h=\"46\"/>\n  <text x=\"345.0\" y=\"52.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Hdr == 0x00 &amp;&amp; Ftr == 0x00 ?</text>\n  <text x=\"345.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Đã gọi Ea_InvalidateBlock</text>\n  <rect x=\"230\" y=\"102\" width=\"230\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"230\" data-box-y=\"102\" data-box-w=\"230\" data-box-h=\"50\"/>\n  <text x=\"345.0\" y=\"124.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Hdr[0]==0xA5 &amp;&amp; Ftr[0]==0x5A</text>\n  <text x=\"345.0\" y=\"138.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">&amp;&amp; Hdr[1] == Ftr[1] ?</text>\n  <rect x=\"230\" y=\"176\" width=\"230\" height=\"46\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"230\" data-box-y=\"176\" data-box-w=\"230\" data-box-h=\"46\"/>\n  <text x=\"345.0\" y=\"196.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Mọi trường hợp khác:</text>\n  <text x=\"345.0\" y=\"210.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">(0xFF rỗng hoặc lệch Counter)</text>\n  <rect x=\"520\" y=\"32\" width=\"235\" height=\"46\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"520\" data-box-y=\"32\" data-box-w=\"235\" data-box-h=\"46\"/>\n  <text x=\"637.5\" y=\"52.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Trả MEMIF_BLOCK_INVALID</text>\n  <text x=\"637.5\" y=\"66.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gọi NvM_JobErrorNotification()</text>\n  <rect x=\"520\" y=\"102\" width=\"235\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"520\" data-box-y=\"102\" data-box-w=\"235\" data-box-h=\"50\"/>\n  <text x=\"637.5\" y=\"124.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Copy Payload vào RamPtr</text>\n  <text x=\"637.5\" y=\"138.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Trả MEMIF_JOB_OK</text>\n  <rect x=\"520\" y=\"176\" width=\"235\" height=\"46\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"520\" data-box-y=\"176\" data-box-w=\"235\" data-box-h=\"46\"/>\n  <text x=\"637.5\" y=\"196.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MEMIF_BLOCK_INCONSISTENT</text>\n  <text x=\"637.5\" y=\"210.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gọi NvM_JobErrorNotification()</text>\n  <path d=\"M180,95 L205,95 L205,55 L230,55\" fill=\"none\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <line x1=\"180\" y1=\"127\" x2=\"230\" y2=\"127\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <path d=\"M180,115 L205,115 L205,199 L230,199\" fill=\"none\" stroke=\"var(--err)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrErr)\"/>\n  <line x1=\"460\" y1=\"55\" x2=\"520\" y2=\"55\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <line x1=\"460\" y1=\"127\" x2=\"520\" y2=\"127\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <line x1=\"460\" y1=\"199\" x2=\"520\" y2=\"199\" stroke=\"var(--err)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrErr)\"/>\n  <g class=\"hb-pill\" data-px=\"473.0\" data-py=\"34.5\" data-pw=\"34\" data-ph=\"15\">\n    <rect x=\"473.0\" y=\"34.5\" width=\"34\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--warn)\" stroke-width=\"1\"/>\n    <text x=\"490\" y=\"45.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--warn)\">YES</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"473.0\" data-py=\"106.5\" data-pw=\"34\" data-ph=\"15\">\n    <rect x=\"473.0\" y=\"106.5\" width=\"34\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"490\" y=\"117.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">YES</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"472.0\" data-py=\"178.5\" data-pw=\"36\" data-ph=\"15\">\n    <rect x=\"472.0\" y=\"178.5\" width=\"36\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--err)\" stroke-width=\"1\"/>\n    <text x=\"490\" y=\"189.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--err)\">ELSE</text>\n  </g>\n</svg></div><div class=\"hb-card\"><h3>Phản Ứng Của NvM Trước Từng Mã Lỗi</h3><table class=\"tbl\"><thead><tr><th>JobResult từ Ea</th><th>Ý nghĩa tại tầng Ea</th><th>Hành động tiếp theo của NvM</th></tr></thead><tbody><tr><td><code>MEMIF_JOB_OK</code></td><td>Hdr 0xA5 &amp; Ftr 0x5A khớp Cnt</td><td>Kiểm tra CRC; nếu đạt → copy vào RAM SWC</td></tr><tr><td><code>MEMIF_BLOCK_INVALID</code></td><td>Hdr == 0x0000 (Invalidate)</td><td>Ghi nhận Block rỗng hợp lệ, nạp ROM Default nếu cấu hình</td></tr><tr><td><code>MEMIF_BLOCK_INCONSISTENT</code></td><td>Dữ liệu hỏng / sập nguồn / mới tinh 0xFF</td><td>Tự động thử Read Redundant/Wear Slot cũ hoặc nạp ROM Default</td></tr></tbody></table></div>"
      },
      {
        "title": "3.4 Invalidate vs Erase",
        "html": "<div class=\"hb-card\"><h3>So Sánh Ea_InvalidateBlock() vs Ea_EraseImmediateBlock()</h3><table class=\"tbl\"><thead><tr><th>Tiêu chí</th><th>Ea_InvalidateBlock(BlkNo) [0x07]</th><th>Ea_EraseImmediateBlock(BlkNo) [0x09]</th></tr></thead><tbody><tr><td><b>Mục đích</b></td><td>Hủy bỏ dữ liệu cũ (vd: xóa thông tin nhạy cảm / reset factory) mà không xóa toàn slot</td><td>Xóa trắng sẵn ô nhớ trước khi sự kiện khẩn cấp xảy ra</td></tr><tr><td><b>Byte ghi xuống HW</b></td><td>Ghi đè <code>0x00, 0x00</code> vào 2 byte Header (tốn ít thời gian ghi nhất)</td><td>Gọi <code>Eep_Erase()</code> đưa toàn bộ <code>SlotSize</code> byte về <code>0xFF</code></td></tr><tr><td><b>Điều kiện cấu hình</b></td><td>Mọi Block hợp lệ đều gọi được</td><td>Bắt buộc <code>EaImmediateData == TRUE</code></td></tr><tr><td><b>Kết quả Ea_Read sau đó</b></td><td><code>MEMIF_BLOCK_INVALID</code></td><td><code>MEMIF_BLOCK_INCONSISTENT</code> (vì toàn vùng là <code>0xFF</code>)</td></tr></tbody></table></div>"
      }
    ]
  },
  {
    "id": 3,
    "title": "4. Bất Đồng Bộ, Immediate & Polling",
    "subTabs": [
      {
        "title": "4.1 Máy Trạng Thái Ea",
        "html": "<div class=\"hb-card\"><h3>4 Trạng Thái Chuẩn Của Ea_GetStatus() : MemIf_StatusType</h3><p>Là module trừu tượng bất đồng bộ, mọi API truyền nhận dữ liệu của Ea chỉ xác nhận đưa vào hàng đợi ngay (<code>E_OK</code>) rồi xử lý dần trong <code>Ea_MainFunction()</code>.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 178\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Máy trạng thái Ea_GetStatus\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Máy Trạng Thái Module Ea (Ea_GetStatus() : MemIf_StatusType)</text>\n  <rect x=\"25\" y=\"76\" width=\"150\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"76\" data-box-w=\"150\" data-box-h=\"54\"/>\n  <text x=\"100.0\" y=\"94.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MEMIF_UNINIT</text>\n  <text x=\"100.0\" y=\"107.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Sau Power-On Reset</text>\n  <text x=\"100.0\" y=\"121.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">API ngoài Init -&gt; DET</text>\n  <rect x=\"220\" y=\"76\" width=\"165\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"220\" data-box-y=\"76\" data-box-w=\"165\" data-box-h=\"54\"/>\n  <text x=\"302.5\" y=\"94.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MEMIF_BUSY_INTERNAL</text>\n  <text x=\"302.5\" y=\"107.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ea_Init() đang chạy</text>\n  <text x=\"302.5\" y=\"121.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Chờ 1 MainFunction</text>\n  <rect x=\"435\" y=\"76\" width=\"145\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"2.2\" data-box-x=\"435\" data-box-y=\"76\" data-box-w=\"145\" data-box-h=\"54\"/>\n  <text x=\"507.5\" y=\"94.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MEMIF_IDLE</text>\n  <text x=\"507.5\" y=\"107.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Sẵn sàng nhận lệnh</text>\n  <text x=\"507.5\" y=\"121.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Read/Write/Invalidate</text>\n  <rect x=\"620\" y=\"76\" width=\"135\" height=\"54\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"620\" data-box-y=\"76\" data-box-w=\"135\" data-box-h=\"54\"/>\n  <text x=\"687.5\" y=\"94.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MEMIF_BUSY</text>\n  <text x=\"687.5\" y=\"107.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Đang chạy Job + Eep</text>\n  <text x=\"687.5\" y=\"121.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Từ chối Job mới (0x06)</text>\n  <line x1=\"175\" y1=\"103\" x2=\"220\" y2=\"103\" stroke=\"var(--pur)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrPur)\"/>\n  <line x1=\"385\" y1=\"103\" x2=\"435\" y2=\"103\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <path d=\"M580,92 L620,92\" fill=\"none\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <path d=\"M620,115 L580,115\" fill=\"none\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <g class=\"hb-pill\" data-px=\"170.0\" data-py=\"54.5\" data-pw=\"54\" data-ph=\"15\">\n    <rect x=\"170.0\" y=\"54.5\" width=\"54\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--pur)\" stroke-width=\"1\"/>\n    <text x=\"197\" y=\"65.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--pur)\">Ea_Init()</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"380.0\" data-py=\"54.5\" data-pw=\"60\" data-ph=\"15\">\n    <rect x=\"380.0\" y=\"54.5\" width=\"60\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"410\" y=\"65.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">MainFn OK</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"574.0\" data-py=\"50.5\" data-pw=\"52\" data-ph=\"15\">\n    <rect x=\"574.0\" y=\"50.5\" width=\"52\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--warn)\" stroke-width=\"1\"/>\n    <text x=\"600\" y=\"61.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--warn)\">API Req</text>\n  </g>\n  <g class=\"hb-pill\" data-px=\"564.0\" data-py=\"140.5\" data-pw=\"72\" data-ph=\"15\">\n    <rect x=\"564.0\" y=\"140.5\" width=\"72\" height=\"15\" rx=\"4\" fill=\"var(--bg)\" stroke=\"var(--ok)\" stroke-width=\"1\"/>\n    <text x=\"600\" y=\"151.2\" text-anchor=\"middle\" font-size=\"8.8\" font-weight=\"700\" fill=\"var(--ok)\">Done/Cancel</text>\n  </g>\n  <line x1=\"600\" y1=\"70\" x2=\"600\" y2=\"88\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <line x1=\"600\" y1=\"139\" x2=\"600\" y2=\"120\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n</svg></div><div class=\"hb-card\"><h3>Quy Tắc Chuyển Trạng Thái</h3><ul><li><code>MEMIF_UNINIT → MEMIF_BUSY_INTERNAL</code>: Khi <code>Ea_Init()</code> bắt đầu khởi tạo nội bộ.</li><li><code>MEMIF_BUSY_INTERNAL → MEMIF_IDLE</code>: Khi hoàn tất quét cấu hình Block/Wear-Slots.</li><li><code>MEMIF_IDLE → MEMIF_BUSY</code>: Khi nhận thành công lệnh <code>Read / Write / Invalidate / EraseImmediate</code>.</li><li><code>MEMIF_BUSY → MEMIF_IDLE</code>: Khi Job kết thúc (<code>JOB_OK / FAILED / INCONSISTENT / INVALID</code>) hoặc bị hủy bởi <code>Ea_Cancel()</code>.</li></ul></div>"
      },
      {
        "title": "4.2 Immediate & Pre-Erase",
        "html": "<div class=\"hb-card\"><h3>Cơ Chế Xử Lý Khẩn Cấp Cho Dữ Liệu Túi Khí / Crash Event</h3><p>Khi tai nạn xảy ra, điện áp bình ắc quy có thể sụt trong vài chục mili-giây. Để kịp ghi khối <code>Blk_Crash_Imm</code> trước khi mất nguồn hoàn toàn, AUTOSAR thiết kế cơ chế <b>Pre-Erase + ImmediateWrite</b>.</p><svg class=\"hb-svg\" viewBox=\"0 0 780 204\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Immediate Data và Pre-Erase\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Tối Ưu Dữ Liệu Khẩn Cấp (Crash Data): Ea_EraseImmediateBlock vs Normal Write</text>\n  <text x=\"25\" y=\"44\" text-anchor=\"start\" font-size=\"9.8\" font-weight=\"700\" fill=\"var(--pur)\">Luồng A — EaImmediateData = TRUE + Pre-Erase (Xóa sẵn trước va chạm):</text>\n  <rect x=\"25\" y=\"54\" width=\"210\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"54\" data-box-w=\"210\" data-box-h=\"44\"/>\n  <text x=\"130.0\" y=\"73.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">1. Lúc chạy bình thường (Idle)</text>\n  <text x=\"130.0\" y=\"87.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ea_EraseImmediateBlock(4) -&gt; 0xFF</text>\n  <rect x=\"275\" y=\"54\" width=\"200\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"275\" data-box-y=\"54\" data-box-w=\"200\" data-box-h=\"44\"/>\n  <text x=\"375.0\" y=\"73.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">2. Sự kiện Crash xảy ra!</text>\n  <text x=\"375.0\" y=\"87.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ea_Write(4, CrashData)</text>\n  <rect x=\"515\" y=\"54\" width=\"240\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"515\" data-box-y=\"54\" data-box-w=\"240\" data-box-h=\"44\"/>\n  <text x=\"635.0\" y=\"73.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">3. Ghi thẳng không cần xóa!</text>\n  <text x=\"635.0\" y=\"87.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Tiết kiệm tối đa thời gian trước sập pin</text>\n  <line x1=\"235\" y1=\"76\" x2=\"275\" y2=\"76\" stroke=\"var(--pur)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrPur)\"/>\n  <line x1=\"475\" y1=\"76\" x2=\"515\" y2=\"76\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <text x=\"25\" y=\"130\" text-anchor=\"start\" font-size=\"9.8\" font-weight=\"700\" fill=\"var(--err)\">Luồng B — EaImmediateData = FALSE mà gọi Ea_EraseImmediateBlock():</text>\n  <rect x=\"25\" y=\"140\" width=\"280\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"140\" data-box-w=\"280\" data-box-h=\"44\"/>\n  <text x=\"165.0\" y=\"159.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Kiểm tra StrictImmediateEraseCheck</text>\n  <text x=\"165.0\" y=\"173.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Block #1 có EaImmediateData == FALSE</text>\n  <rect x=\"350\" y=\"140\" width=\"405\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"350\" data-box-y=\"140\" data-box-w=\"405\" data-box-h=\"44\"/>\n  <text x=\"552.5\" y=\"159.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Bị từ chối ngay lập tức (Return E_NOT_OK)</text>\n  <text x=\"552.5\" y=\"173.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Báo lỗi DET EA_E_INVALID_BLOCK_NO / State Guard!</text>\n  <line x1=\"305\" y1=\"162\" x2=\"350\" y2=\"162\" stroke=\"var(--err)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrErr)\"/>\n</svg></div><div class=\"hb-card\"><h3>Lưu Ý Thực Tế Khi Dùng EaImmediateData</h3><p>Trong Simulator, <b>Blk #4 (Blk_Crash_Imm)</b> được bật <code>ImmediateData = TRUE</code>, còn <b>Blk #1</b> mặc định <code>FALSE</code>. Bạn có thể bấm thử <b>EraseImm</b> lên Blk #1 trong Quick Actions để xem <code>StrictImmediateEraseCheck</code> bắt lỗi ngay tức khắc!</p></div>"
      },
      {
        "title": "4.3 Callback vs Polling",
        "html": "<div class=\"hb-card\"><h3>Hai Phương Thức Nhận Kết Quả Từ Eep Driver</h3><p><code>EaPollingMode</code> trong Container <code>EaGeneral</code> quyết định cách Ea biết được khi nào <code>Eep Driver</code> thực thi xong một Sub-Job:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 198\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Callback vs Polling Mode\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Hai Cơ Chế Giao Tiếp Ea ↔ Eep: Callback Mode vs Polling Mode (EaPollingMode)</text>\n  <rect x=\"25\" y=\"42\" width=\"345\" height=\"136\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"345\" data-box-h=\"136\"/>\n  <text x=\"197.5\" y=\"88.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"197.5\" y=\"101.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"128.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"142.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--ok)\">EaPollingMode = FALSE (Callback Driven)</text>\n  <rect x=\"42\" y=\"74\" width=\"135\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"42\" data-box-y=\"74\" data-box-w=\"135\" data-box-h=\"40\"/>\n  <text x=\"109.5\" y=\"91.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ea_MainFunction</text>\n  <text x=\"109.5\" y=\"105.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gọi Eep_Write()</text>\n  <rect x=\"215\" y=\"74\" width=\"138\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"215\" data-box-y=\"74\" data-box-w=\"138\" data-box-h=\"40\"/>\n  <text x=\"284.0\" y=\"91.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Eep_MainFunction</text>\n  <text x=\"284.0\" y=\"105.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Xong -&gt; Gọi Callback</text>\n  <rect x=\"42\" y=\"130\" width=\"311\" height=\"36\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"42\" data-box-y=\"130\" data-box-w=\"311\" data-box-h=\"36\"/>\n  <text x=\"197.5\" y=\"145.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ea_JobEndNotification() [0x10]</text>\n  <text x=\"197.5\" y=\"159.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Kích hoạt ngay NvM_JobEndNotification()</text>\n  <line x1=\"177\" y1=\"94\" x2=\"215\" y2=\"94\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <line x1=\"284\" y1=\"114\" x2=\"284\" y2=\"130\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <rect x=\"410\" y=\"42\" width=\"345\" height=\"136\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"410\" data-box-y=\"42\" data-box-w=\"345\" data-box-h=\"136\"/>\n  <text x=\"582.5\" y=\"88.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"582.5\" y=\"101.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"115.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"128.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"142.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--warn)\">EaPollingMode = TRUE (Polling Driven)</text>\n  <rect x=\"427\" y=\"74\" width=\"135\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"427\" data-box-y=\"74\" data-box-w=\"135\" data-box-h=\"40\"/>\n  <text x=\"494.5\" y=\"91.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ea_MainFunction</text>\n  <text x=\"494.5\" y=\"105.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gọi Eep_Write()</text>\n  <rect x=\"600\" y=\"74\" width=\"138\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"600\" data-box-y=\"74\" data-box-w=\"138\" data-box-h=\"40\"/>\n  <text x=\"669.0\" y=\"91.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Eep_MainFunction</text>\n  <text x=\"669.0\" y=\"105.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Chỉ cập nhật Flag nội</text>\n  <rect x=\"427\" y=\"130\" width=\"311\" height=\"36\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"427\" data-box-y=\"130\" data-box-w=\"311\" data-box-h=\"36\"/>\n  <text x=\"582.5\" y=\"145.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Chu kỳ sau Ea hỏi: Eep_GetJobResult()</text>\n  <text x=\"582.5\" y=\"159.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Nếu MEMIF_JOB_OK -&gt; Báo lên NvM</text>\n  <line x1=\"562\" y1=\"94\" x2=\"600\" y2=\"94\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <line x1=\"669\" y1=\"114\" x2=\"669\" y2=\"130\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n</svg></div><div class=\"hb-card\"><h3>So Sánh Độ Trễ & Cấu Hình Interrupt</h3><table class=\"tbl\"><thead><tr><th>Tham số / Đặc tính</th><th>EaPollingMode = FALSE (Callback)</th><th>EaPollingMode = TRUE (Polling)</th></tr></thead><tbody><tr><td><b>Cơ chế báo từ Eep</b></td><td>Ngắt/Callback gọi <code>Ea_JobEndNotification()</code> ngay</td><td>Ea tự gọi <code>Eep_GetJobResult()</code> trong <code>Ea_MainFunction()</code></td></tr><tr><td><b>Độ trễ phản hồi</b></td><td>Nhanh nhất (gần như tức thời khi xong)</td><td>Trễ tối đa thêm 1 chu kỳ <code>EaMainFunctionPeriod</code> (5ms)</td></tr><tr><td><b>Yêu cầu cấu hình Eep</b></td><td>Phải nối Notification Ptr sang hàm của Ea</td><td>Không cần cấu hình interrupt callback của Eep</td></tr></tbody></table></div>"
      },
      {
        "title": "4.4 Ea_SetMode & Ea_Cancel",
        "html": "<div class=\"hb-card\"><h3>Điều Chỉnh Băng Thông (SLOW/FAST) Và Hủy Job Khẩn Cấp</h3><table class=\"tbl\"><thead><tr><th>API</th><th>Chức năng &amp; Ngữ cảnh dùng</th><th>Hệ quả tại Ea &amp; Eep</th></tr></thead><tbody><tr><td><code>Ea_SetMode(MEMIF_MODE_FAST)</code></td><td>Được BswM/EcuM gọi trong pha <b>NvM_ReadAll</b> khi bật khóa điện (Startup) hoặc <b>WriteAll</b> lúc tắt máy</td><td>Tăng Chunk Size mỗi tick (ví dụ từ 8B → 32B/tick), giúp khởi động ECU nhanh hơn nhiều lần</td></tr><tr><td><code>Ea_SetMode(MEMIF_MODE_SLOW)</code></td><td>Gọi sau khi vào chu trình chạy bình thường</td><td>Giảm tải SPI/CPU xuống 8B/tick để nhường ưu tiên cho các tác vụ điều khiển động cơ/phanh</td></tr><tr><td><code>Ea_Cancel()</code> [0x04]</td><td>Hủy Job hiện tại khi cần nhường ngay EEPROM cho khối khẩn cấp hoặc Shutdown</td><td>Gọi xuống <code>Eep_Cancel()</code>, đặt JobResult thành <code>MEMIF_JOB_CANCELED</code>, đưa Ea về <code>MEMIF_IDLE</code></td></tr></tbody></table></div>"
      }
    ]
  },
  {
    "id": 4,
    "title": "5. So Sánh Chuyên Sâu: Ea vs Fee",
    "subTabs": [
      {
        "title": "5.1 EEPROM vs Data Flash",
        "html": "<div class=\"hb-card\"><h3>Khác Biệt Vật Lý Giữa Ea (EEPROM) Và Fee (Data Flash)</h3><p>Dù cùng đứng ngang hàng dưới tầng <code>MemIf</code> với bộ API giống hệt nhau (<code>Read/Write/Invalidate/EraseImmediate/Cancel/SetMode</code>), kiến trúc bên trong của <b>Ea</b> và <b>Fee</b> khác hoàn toàn do bản chất silicon bên dưới:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 208\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"So sánh Ea vs Fee phần cứng\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">So Sánh Phần Cứng &amp; MCAL: Ea (EEPROM) vs Fee (Data Flash)</text>\n  <rect x=\"25\" y=\"42\" width=\"345\" height=\"148\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--ok)\" stroke-width=\"2\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"345\" data-box-h=\"148\"/>\n  <text x=\"197.5\" y=\"87.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"197.5\" y=\"101.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"114.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"128.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"141.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"155.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197\" y=\"62\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"var(--ok)\">Đường 1: Ea + Eep (External EEPROM)</text>\n  <rect x=\"45\" y=\"76\" width=\"305\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"45\" data-box-y=\"76\" data-box-w=\"305\" data-box-h=\"44\"/>\n  <text x=\"197.5\" y=\"95.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ea (ModuleId=40) → Eep Driver (90)</text>\n  <text x=\"197.5\" y=\"109.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ghi / xóa từng Byte hoặc Page (4B/8B/16B)</text>\n  <rect x=\"45\" y=\"132\" width=\"305\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"45\" data-box-y=\"132\" data-box-w=\"305\" data-box-h=\"44\"/>\n  <text x=\"197.5\" y=\"151.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">External SPI / I2C EEPROM</text>\n  <text x=\"197.5\" y=\"165.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Độ bền cao: 100,000 .. 1,000,000+ cycles</text>\n  <rect x=\"410\" y=\"42\" width=\"345\" height=\"148\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--cyan)\" stroke-width=\"2\" data-box-x=\"410\" data-box-y=\"42\" data-box-w=\"345\" data-box-h=\"148\"/>\n  <text x=\"582.5\" y=\"87.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"582.5\" y=\"101.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"114.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"128.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"141.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"155.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582\" y=\"62\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"var(--cyan)\">Đường 2: Fee + Fls (Internal Data Flash)</text>\n  <rect x=\"430\" y=\"76\" width=\"305\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"430\" data-box-y=\"76\" data-box-w=\"305\" data-box-h=\"44\"/>\n  <text x=\"582.5\" y=\"95.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Fee (ModuleId=21) → Fls Driver (92)</text>\n  <text x=\"582.5\" y=\"109.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ghi Page nhưng XÓA THEO CẢ SECTOR (4KB-64KB)</text>\n  <rect x=\"430\" y=\"132\" width=\"305\" height=\"44\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"430\" data-box-y=\"132\" data-box-w=\"305\" data-box-h=\"44\"/>\n  <text x=\"582.5\" y=\"151.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Internal MCU Data Flash</text>\n  <text x=\"582.5\" y=\"165.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Độ bền thấp hơn: 10k-100k cycles; dung lượng lớn</text>\n</svg></div>"
      },
      {
        "title": "5.2 Fixed-Slot vs Garbage Collect",
        "html": "<div class=\"hb-card\"><h3>Tại Sao Ea Không Cần Garbage Collection Như Fee?</h3><p>Flash bắt buộc phải <b>xóa nguyên Sector lớn (4KB–64KB)</b> trước khi ghi đè lại, nên <b>Fee</b> phải ghi nối đuôi (Append-Only) và chạy Garbage Collection rất tốn CPU/thời gian khi đầy Sector. Ngược lại, <b>EEPROM</b> hỗ trợ ghi/xóa từng byte hoặc page nhỏ (4B–16B), nên <b>Ea</b> dùng địa chỉ Slot cố định:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 198\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Ea Fixed Slot vs Fee Garbage Collection\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Quản Lý Ô Nhớ: Ea Xoay Vòng Slot Cố Định vs Fee Append-Only + Garbage Collection</text>\n  <rect x=\"25\" y=\"44\" width=\"345\" height=\"136\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"44\" data-box-w=\"345\" data-box-h=\"136\"/>\n  <text x=\"197.5\" y=\"90.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"197.5\" y=\"103.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"117.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"130.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197.5\" y=\"144.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"197\" y=\"64\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--ok)\">Ea: Static Fixed-Slot Wear-Leveling</text>\n  <rect x=\"45\" y=\"78\" width=\"305\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"45\" data-box-y=\"78\" data-box-w=\"305\" data-box-h=\"40\"/>\n  <text x=\"197.5\" y=\"95.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Địa chỉ Slot tính tĩnh lúc cấu hình</text>\n  <text x=\"197.5\" y=\"109.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Ghi đè trực tiếp lên Slot kế (k % N)</text>\n  <rect x=\"45\" y=\"128\" width=\"305\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"45\" data-box-y=\"128\" data-box-w=\"305\" data-box-h=\"40\"/>\n  <text x=\"197.5\" y=\"145.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">KHÔNG cần Garbage Collection (GC)</text>\n  <text x=\"197.5\" y=\"159.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Thời gian ghi ổn định, xác định (Deterministic)</text>\n  <rect x=\"410\" y=\"44\" width=\"345\" height=\"136\" rx=\"7\" fill=\"var(--bg2)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"410\" data-box-y=\"44\" data-box-w=\"345\" data-box-h=\"136\"/>\n  <text x=\"582.5\" y=\"90.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\"></text>\n  <text x=\"582.5\" y=\"103.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"117.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"130.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582.5\" y=\"144.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\"></text>\n  <text x=\"582\" y=\"64\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--pur)\">Fee: Append-Only Log + Sector Switch GC</text>\n  <rect x=\"430\" y=\"78\" width=\"305\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"430\" data-box-y=\"78\" data-box-w=\"305\" data-box-h=\"40\"/>\n  <text x=\"582.5\" y=\"95.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Ghi nối đuôi liên tục vào Virtual Sector</text>\n  <text x=\"582.5\" y=\"109.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Block cũ đánh dấu INVALID nằm rải rác</text>\n  <rect x=\"430\" y=\"128\" width=\"305\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"430\" data-box-y=\"128\" data-box-w=\"305\" data-box-h=\"40\"/>\n  <text x=\"582.5\" y=\"145.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Khi Sector đầy -&gt; Phải chạy GC Copy &amp; Erase</text>\n  <text x=\"582.5\" y=\"159.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Gây trễ tức thời khi dọn Sector Flash</text>\n</svg></div><div class=\"hb-card\"><h3>Bảng So Sánh Toàn Diện Ea vs Fee</h3><table class=\"tbl\"><thead><tr><th>Tiêu chí</th><th>Ea (EEPROM Abstraction - ID 40)</th><th>Fee (Flash EEPROM Emulation - ID 21)</th></tr></thead><tbody><tr><td><b>MCAL Driver bên dưới</b></td><td><code>Eep</code> (ModuleId = 90)</td><td><code>Fls</code> (ModuleId = 92)</td></tr><tr><td><b>Phần cứng lưu trữ</b></td><td>External SPI / I2C EEPROM</td><td>Internal MCU Data Flash (hoặc PFlash)</td></tr><tr><td><b>Đơn vị xóa tối thiểu</b></td><td>Byte / Small Page (4..32 Bytes)</td><td>Toàn bộ Flash Sector (4 KB .. 64 KB)</td></tr><tr><td><b>Vị trí ghi dữ liệu</b></td><td>Fixed Physical Slot Address (+ Rotation)</td><td>Dynamic Append-Only Log trong Sector đang Active</td></tr><tr><td><b>Garbage Collection (GC)</b></td><td><b>Không có GC</b> (Thời gian đáp ứng ổn định)</td><td><b>Bắt buộc có GC</b> khi chuyển Sector</td></tr><tr><td><b>Giá trị Byte Erased</b></td><td>Mặc định <code>0xFF</code></td><td>Tùy MCU Silicon (thường <code>0xFF</code> hoặc <code>0x00</code>)</td></tr></tbody></table></div>"
      },
      {
        "title": "5.3 Kiến Trúc Hybrid Dual-Device",
        "html": "<div class=\"hb-card\"><h3>Khi Nào ECU Dùng Đồng Thời Cả Ea Và Fee?</h3><p>Nhiều ECU hiện đại kết hợp Internal Data Flash cho dữ liệu lớn ít đổi, đồng thời gắn thêm một chip External EEPROM nhỏ bền bỉ cho Odometer ghi liên tục mỗi kilômét:</p><svg class=\"hb-svg\" viewBox=\"0 0 780 234\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Kiến trúc Hybrid ECU Ea + Fee\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Kiến Trúc Hybrid ECU Kết Hợp Ea + Fee Dưới Tầng MemIf</text>\n  <rect x=\"270\" y=\"34\" width=\"240\" height=\"42\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"270\" data-box-y=\"34\" data-box-w=\"240\" data-box-h=\"42\"/>\n  <text x=\"390.0\" y=\"52.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">NvM Manager</text>\n  <text x=\"390.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Phân loại Block theo tần suất &amp; kích thước</text>\n  <rect x=\"270\" y=\"96\" width=\"240\" height=\"40\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"270\" data-box-y=\"96\" data-box-w=\"240\" data-box-h=\"40\"/>\n  <text x=\"390.0\" y=\"113.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">MemIf Abstraction</text>\n  <text x=\"390.0\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">DeviceIndex 0 -&gt; Ea | DeviceIndex 1 -&gt; Fee</text>\n  <rect x=\"45\" y=\"162\" width=\"310\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"45\" data-box-y=\"162\" data-box-w=\"310\" data-box-h=\"56\"/>\n  <text x=\"200.0\" y=\"187.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">DeviceIndex=0: Ea → Eep → Ext EEPROM</text>\n  <text x=\"200.0\" y=\"201.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Dùng cho Odometer, CrashData, IMM</text>\n  <rect x=\"425\" y=\"162\" width=\"310\" height=\"56\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"425\" data-box-y=\"162\" data-box-w=\"310\" data-box-h=\"56\"/>\n  <text x=\"580.0\" y=\"187.5\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">DeviceIndex=1: Fee → Fls → Int DFlash</text>\n  <text x=\"580.0\" y=\"201.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Dùng cho DTC Dem (&gt;2KB), VIN, Calib lớn</text>\n  <line x1=\"390\" y1=\"76\" x2=\"390\" y2=\"96\" stroke=\"var(--warn)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrWarn)\"/>\n  <path d=\"M330,136 L330,149 L200,149 L200,162\" fill=\"none\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n  <path d=\"M450,136 L450,149 L580,149 L580,162\" fill=\"none\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrCyan)\"/>\n</svg></div>"
      },
      {
        "title": "5.4 Tiêu Chí Chọn Ea Cho Dự Án",
        "html": "<div class=\"hb-card\"><h3>Checklist Lựa Chọn Ea Trong Thực Tế Ô Tô</h3><ul><li><b>Chọn Ea + Eep khi:</b> ECU đã có sẵn EEPROM ngoài, yêu cầu số chu kỳ ghi cực cao (&gt;300k–1M lần như Odometer/Trip meter), hoặc hệ thống an toàn yêu cầu <b>Real-Time Deterministic</b> không chấp nhận độ trễ bất ngờ từ Flash Garbage Collection.</li><li><b>Chọn Fee + Fls khi:</b> Muốn cắt giảm chi phí linh kiện BOM (bỏ chip EEPROM ngoài), chỉ lưu cấu hình, lịch sử DTC kích thước lớn vài KB ít khi ghi đè.</li><li><b>Kiến trúc AUTOSAR đảm bảo:</b> Tầng NvM &amp; SWC không phải sửa một dòng code nào khi chuyển đổi Block giữa <code>Ea</code> và <code>Fee</code> — chỉ cần đổi <code>DeviceIndex</code> trong ECUC!</li></ul></div>"
      }
    ]
  },
  {
    "id": 5,
    "title": "6. API R23-11, Lỗi DET & 36 ECUC",
    "subTabs": [
      {
        "title": "6.1 Danh Mục API R23-11",
        "html": "<div class=\"hb-card\"><h3>Toàn Bộ Giao Diện API & Notification Chuẩn AUTOSAR Classic Ea R23-11</h3><svg class=\"hb-svg\" viewBox=\"0 0 780 204\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Danh mục API AUTOSAR Ea R23-11\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Danh Mục API &amp; Callback Chuẩn AUTOSAR Classic Ea R23-11 (ModuleId=40)</text>\n  <rect x=\"25\" y=\"42\" width=\"230\" height=\"146\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"42\" data-box-w=\"230\" data-box-h=\"146\"/>\n  <text x=\"140.0\" y=\"86.5\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--pri)\">Quản Lý &amp; Trạng Thái</text>\n  <text x=\"140.0\" y=\"100.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x00 Ea_Init(ConfigPtr)</text>\n  <text x=\"140.0\" y=\"113.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x01 Ea_SetMode(Mode)</text>\n  <text x=\"140.0\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x05 Ea_GetStatus()</text>\n  <text x=\"140.0\" y=\"140.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x06 Ea_GetJobResult()</text>\n  <text x=\"140.0\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x08 Ea_GetVersionInfo()</text>\n  <rect x=\"275\" y=\"42\" width=\"230\" height=\"146\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"275\" data-box-y=\"42\" data-box-w=\"230\" data-box-h=\"146\"/>\n  <text x=\"390.0\" y=\"86.5\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--ok)\">Thao Tác Dữ Liệu Bất Đồng Bộ</text>\n  <text x=\"390.0\" y=\"100.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x02 Ea_Read(Blk, Off, Ptr, Len)</text>\n  <text x=\"390.0\" y=\"113.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x03 Ea_Write(Blk, DataPtr)</text>\n  <text x=\"390.0\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x04 Ea_Cancel()</text>\n  <text x=\"390.0\" y=\"140.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x07 Ea_InvalidateBlock(Blk)</text>\n  <text x=\"390.0\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x09 Ea_EraseImmediateBlock(Blk)</text>\n  <rect x=\"525\" y=\"42\" width=\"230\" height=\"146\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"525\" data-box-y=\"42\" data-box-w=\"230\" data-box-h=\"146\"/>\n  <text x=\"640.0\" y=\"86.5\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--pur)\">Scheduled &amp; Callback Eep</text>\n  <text x=\"640.0\" y=\"100.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x12 Ea_MainFunction()</text>\n  <text x=\"640.0\" y=\"113.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x10 Ea_JobEndNotification()</text>\n  <text x=\"640.0\" y=\"127.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">0x11 Ea_JobErrorNotification()</text>\n  <text x=\"640.0\" y=\"140.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Notification lên NvM:</text>\n  <text x=\"640.0\" y=\"154.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">NvM_JobEnd / ErrorNotif</text>\n</svg></div><div class=\"hb-card\"><h3>Bảng Service ID & Chữ Ký Hàm Chuẩn</h3><table class=\"tbl\"><thead><tr><th>ServiceId</th><th>Tên Hàm Chuẩn (SWS_Ea)</th><th>Kiểu Gọi</th><th>Mô tả ngắn gọn</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>Ea_Init(const Ea_ConfigType* ConfigPtr)</code></td><td>Sync</td><td>Khởi tạo module &amp; ánh xạ Slot (Post-Build / Link-Time)</td></tr><tr><td><code>0x01</code></td><td><code>Ea_SetMode(MemIf_ModeType Mode)</code></td><td>Sync</td><td>Chuyển tốc độ/chunk giữa SLOW &amp; FAST</td></tr><tr><td><code>0x02</code></td><td><code>Ea_Read(Blk, Off, Ptr, Len)</code></td><td>Async</td><td>Đọc <code>Len</code> bytes từ offset <code>Off</code> của Block</td></tr><tr><td><code>0x03</code></td><td><code>Ea_Write(Blk, DataPtr)</code></td><td>Async</td><td>Ghi toàn bộ Block theo chuỗi 3 pha an toàn</td></tr><tr><td><code>0x04</code></td><td><code>Ea_Cancel(void)</code></td><td>Sync</td><td>Hủy Job đang chạy và gọi <code>Eep_Cancel()</code></td></tr><tr><td><code>0x05</code></td><td><code>Ea_GetStatus(void)</code></td><td>Sync</td><td>Trả về <code>MEMIF_UNINIT / BUSY_INTERNAL / IDLE / BUSY</code></td></tr><tr><td><code>0x06</code></td><td><code>Ea_GetJobResult(void)</code></td><td>Sync</td><td>Trả về <code>JOB_OK / PENDING / FAILED / CANCELED / INCONSISTENT / INVALID</code></td></tr><tr><td><code>0x07</code></td><td><code>Ea_InvalidateBlock(Blk)</code></td><td>Async</td><td>Ghi <code>0x0000</code> vào Header đánh dấu block vô hiệu</td></tr><tr><td><code>0x08</code></td><td><code>Ea_GetVersionInfo(VersionInfoPtr)</code></td><td>Sync</td><td>Lấy VendorId, ModuleId=40, SwVersion</td></tr><tr><td><code>0x09</code></td><td><code>Ea_EraseImmediateBlock(Blk)</code></td><td>Async</td><td>Pre-erase slot cho block có <code>EaImmediateData=TRUE</code></td></tr><tr><td><code>0x10 / 0x11</code></td><td><code>Ea_JobEnd / JobErrorNotification()</code></td><td>Cbk</td><td>Callback từ Eep Driver báo xong sub-job</td></tr><tr><td><code>0x12</code></td><td><code>Ea_MainFunction(void)</code></td><td>Sched</td><td>Máy trạng thái xử lý bất đồng bộ theo chu kỳ SchM</td></tr></tbody></table></div>"
      },
      {
        "title": "6.2 Lỗi DET & Runtime R23-11",
        "html": "<div class=\"hb-card\"><h3>Chuỗi Kiểm Tra Đầu Vào (Development Error vs Runtime Error)</h3><p>Từ các release mới (R19-11 đến R23-11), AUTOSAR tách rõ <b>Development Errors</b> (lỗi lập trình/cấu hình do bật <code>EaDevErrorDetect</code>) và <b>Runtime Errors</b> (luôn báo qua <code>Det_ReportRuntimeError</code> ngay cả trên bản Production).</p><svg class=\"hb-svg\" viewBox=\"0 0 780 202\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"DET và Runtime Error Guard\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Chuỗi Kiểm Tra Bảo Vệ (DET &amp; Runtime Error Guard) Đầu Hàm API</text>\n  <rect x=\"25\" y=\"44\" width=\"166\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"44\" data-box-w=\"166\" data-box-h=\"62\"/>\n  <text x=\"108.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">1. Init Check</text>\n  <text x=\"108.0\" y=\"79.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">EA_E_UNINIT (0x01)</text>\n  <text x=\"108.0\" y=\"93.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Chưa gọi Ea_Init()</text>\n  <line x1=\"191\" y1=\"75\" x2=\"213\" y2=\"75\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"213\" y=\"44\" width=\"166\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"213\" data-box-y=\"44\" data-box-w=\"166\" data-box-h=\"62\"/>\n  <text x=\"296.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">2. Block Check</text>\n  <text x=\"296.0\" y=\"79.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">EA_E_INVALID_BLOCK_NO (0x02)</text>\n  <text x=\"296.0\" y=\"93.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">BlkNo sai / Không Imm</text>\n  <line x1=\"379\" y1=\"75\" x2=\"401\" y2=\"75\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"401\" y=\"44\" width=\"166\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"401\" data-box-y=\"44\" data-box-w=\"166\" data-box-h=\"62\"/>\n  <text x=\"484.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">3. Ptr &amp; Ofs Check</text>\n  <text x=\"484.0\" y=\"79.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">PTR (0x04) / OFS (0x03)</text>\n  <text x=\"484.0\" y=\"93.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">NULL_PTR / Ofs / Len</text>\n  <line x1=\"567\" y1=\"75\" x2=\"589\" y2=\"75\" stroke=\"var(--pri)\" stroke-width=\"1.6\" marker-end=\"url(#hbArr)\"/>\n  <rect x=\"589\" y=\"44\" width=\"166\" height=\"62\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--warn)\" stroke-width=\"1.5\" data-box-x=\"589\" data-box-y=\"44\" data-box-w=\"166\" data-box-h=\"62\"/>\n  <text x=\"672.0\" y=\"66.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">4. Busy Guard</text>\n  <text x=\"672.0\" y=\"79.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">EA_E_BUSY (0x06 Runtime)</text>\n  <text x=\"672.0\" y=\"93.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Module đang MEMIF_BUSY</text>\n  <rect x=\"25\" y=\"134\" width=\"355\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"134\" data-box-w=\"355\" data-box-h=\"50\"/>\n  <text x=\"202.5\" y=\"150.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Nếu bất kỳ điều kiện nào sai:</text>\n  <text x=\"202.5\" y=\"163.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Det_ReportError / Det_ReportRuntimeError()</text>\n  <text x=\"202.5\" y=\"177.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Trả ngay E_NOT_OK (KHÔNG xuống Eep)!</text>\n  <rect x=\"410\" y=\"134\" width=\"345\" height=\"50\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"410\" data-box-y=\"134\" data-box-w=\"345\" data-box-h=\"50\"/>\n  <text x=\"582.5\" y=\"150.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Nếu vượt qua cả 4 cổng kiểm tra:</text>\n  <text x=\"582.5\" y=\"163.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Set MEMIF_BUSY + MEMIF_JOB_PENDING</text>\n  <text x=\"582.5\" y=\"177.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">-&gt; Đưa Job vào Ea_MainFunction()!</text>\n  <line x1=\"200\" y1=\"106\" x2=\"200\" y2=\"134\" stroke=\"var(--err)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrErr)\"/>\n  <line x1=\"585\" y1=\"106\" x2=\"585\" y2=\"134\" stroke=\"var(--ok)\" stroke-width=\"1.6\" marker-end=\"url(#hbArrOk)\"/>\n</svg></div><div class=\"hb-card\"><h3>Mã Lỗi DET, Runtime & Production DEM</h3><table class=\"tbl\"><thead><tr><th>Mã Lỗi</th><th>Hex</th><th>Phân Loại</th><th>Nguyên Nhân Kích Hoạt</th></tr></thead><tbody><tr><td><code>EA_E_UNINIT</code></td><td><code>0x01</code></td><td>Development</td><td>Gọi API bất kỳ trước khi <code>Ea_Init()</code> xong</td></tr><tr><td><code>EA_E_INVALID_BLOCK_NO</code></td><td><code>0x02</code></td><td>Development</td><td><code>BlockNumber</code> không tồn tại hoặc gọi EraseImm cho Block non-Immediate</td></tr><tr><td><code>EA_E_INVALID_BLOCK_OFS</code></td><td><code>0x03</code></td><td>Development</td><td><code>BlockOffset >= EaBlockSize</code></td></tr><tr><td><code>EA_E_INVALID_DATA_PTR</code></td><td><code>0x04</code></td><td>Development</td><td>Con trỏ <code>DataBufferPtr</code> hoặc <code>VersionInfoPtr</code> là <code>NULL_PTR</code></td></tr><tr><td><code>EA_E_INVALID_BLOCK_LEN</code></td><td><code>0x05</code></td><td>Development</td><td><code>Length == 0</code> hoặc <code>BlockOffset + Length &gt; EaBlockSize</code></td></tr><tr><td><code>EA_E_BUSY</code></td><td><code>0x06</code></td><td><b>Runtime Error</b></td><td>Module đang <code>MEMIF_BUSY</code> mà nhận tiếp yêu cầu mới</td></tr><tr><td><code>EA_E_INVALID_CANCEL</code></td><td><code>0x08</code></td><td><b>Runtime Error</b></td><td>Gọi <code>Ea_Cancel()</code> khi không có Job nào đang chạy (<code>MEMIF_IDLE</code>)</td></tr><tr><td><code>EEP_E_*_FAILED</code></td><td>DEM</td><td>Production HW</td><td>Lỗi phần cứng từ Eep Driver (SPI timeout, checksum/ECC)</td></tr></tbody></table></div>"
      },
      {
        "title": "6.3 Bản Đồ 36 Tham Số ECUC",
        "html": "<div class=\"hb-card\"><h3>6 Nhóm Cấu Hình ECUC Trong Simulator (Hover > 1s Để Xem Tooltip)</h3><svg class=\"hb-svg\" viewBox=\"0 0 780 208\" width=\"100%\" style=\"max-width:780px;height:auto;display:block;margin:8px auto;\" role=\"img\" aria-label=\"Bản đồ 6 container cấu hình ECUC Ea\">\n  <defs>\n    <marker id=\"hbArr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pri)\"/>\n    </marker>\n    <marker id=\"hbArrOk\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--ok)\"/>\n    </marker>\n    <marker id=\"hbArrWarn\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--warn)\"/>\n    </marker>\n    <marker id=\"hbArrErr\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--err)\"/>\n    </marker>\n    <marker id=\"hbArrPur\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--pur)\"/>\n    </marker>\n    <marker id=\"hbArrCyan\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\">\n      <path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"var(--cyan)\"/>\n    </marker>\n  </defs>\n  <text x=\"390\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"var(--txt)\">Bản Đồ 6 Nhóm Cấu Hình ECUC (36 Tham Số Trong Simulator)</text>\n  <rect x=\"25\" y=\"38\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pri)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"38\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"141.0\" y=\"63.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 0: EaGeneral (8)</text>\n  <text x=\"141.0\" y=\"76.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Init, DET, VersionInfo, Polling</text>\n  <text x=\"141.0\" y=\"90.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">SetMode, VPSize, EaIndex, 5ms</text>\n  <rect x=\"275\" y=\"38\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--cyan)\" stroke-width=\"1.5\" data-box-x=\"275\" data-box-y=\"38\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"391.0\" y=\"63.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 1: Callback &amp; Mode (6)</text>\n  <text x=\"391.0\" y=\"76.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">JobEnd/Error Notif Enabled &amp; Name</text>\n  <text x=\"391.0\" y=\"90.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">CurrentMode, BufferAlignment</text>\n  <rect x=\"525\" y=\"38\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"525\" data-box-y=\"38\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"641.0\" y=\"63.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 2: Blk 1 &amp; Dataset 2 (6)</text>\n  <text x=\"641.0\" y=\"76.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk1 (#1, 12B, IMM)</text>\n  <text x=\"641.0\" y=\"90.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk2 Dataset (#8 &amp; #9, 8B)</text>\n  <rect x=\"25\" y=\"120\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--ok)\" stroke-width=\"1.5\" data-box-x=\"25\" data-box-y=\"120\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"141.0\" y=\"145.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 3: Wear &amp; Crash Blk (6)</text>\n  <text x=\"141.0\" y=\"158.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk3 Wear (#3, 4B, 400k -&gt; 4x)</text>\n  <text x=\"141.0\" y=\"172.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">Blk4 Crash (#4, 16B, IMM)</text>\n  <rect x=\"275\" y=\"120\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--pur)\" stroke-width=\"1.5\" data-box-x=\"275\" data-box-y=\"120\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"391.0\" y=\"145.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 4: Published &amp; Eep (5)</text>\n  <text x=\"391.0\" y=\"158.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">EaBlockOverhead=4B, PageOH=0B</text>\n  <text x=\"391.0\" y=\"172.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">EepCycles=100k, Base=0x0000, Chunk</text>\n  <rect x=\"525\" y=\"120\" width=\"232\" height=\"68\" rx=\"7\" fill=\"var(--bg3)\" stroke=\"var(--err)\" stroke-width=\"1.5\" data-box-x=\"525\" data-box-y=\"120\" data-box-w=\"232\" data-box-h=\"68\"/>\n  <text x=\"641.0\" y=\"145.0\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--txt)\">Tab 5: Fault Inject (5)</text>\n  <text x=\"641.0\" y=\"158.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">PowerLossMidWrite, EepHwErr</text>\n  <text x=\"641.0\" y=\"172.0\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"500\" fill=\"var(--mut)\">AutoVerify, StrictImm, NullPtr</text>\n</svg></div><div class=\"hb-card\"><h3>Chú Giải Các Tham Số Ảnh Hưởng Mạnh Nhất</h3><ul><li><code>EaVirtualPageSize</code> &amp; <code>EaBlockOverhead</code>: Thay đổi trực tiếp kích thước căn chỉnh vật lý của mọi Block trong EEPROM Map.</li><li><code>EaPollingMode</code>: Bật/tắt đường nhận kết quả Polling (<code>Eep_GetJobResult</code>) vs Callback (<code>Ea_JobEndNotification</code>).</li><li><code>Blk3_NumberOfWriteCycles</code> &amp; <code>EepAllowedWriteCycles</code>: Quyết định tự động số lượng Slot Wear-Leveling xoay vòng cho Odometer.</li><li><b>Tab 5 Fault Injection:</b> Gồm 5 công tắc mô phỏng mất nguồn giữa pha ghi, lỗi phần cứng EEPROM, NULL_PTR test, và strict check.</li></ul></div>"
      },
      {
        "title": "6.4 Hướng Dẫn 14 Kịch Bản & Export",
        "html": "<div class=\"hb-card\"><h3>Bản Đồ 14 Kịch Bản Tương Tác (S1–S14) & Xuất Code Cấu Hình</h3><table class=\"tbl\"><thead><tr><th>Nhóm</th><th>Kịch Bản</th><th>Trọng Tâm Khám Phá</th></tr></thead><tbody><tr><td>Nhóm 1</td><td><b>S1 – S4</b></td><td>Init từ UNINIT, Luồng ghi 3 pha SWC→EEPROM, Ea_Read offset/len, Dataset #8/#9 &amp; VP Padding</td></tr><tr><td>Nhóm 2</td><td><b>S5 – S8</b></td><td>Power-Loss Mid-Write (<code>INCONSISTENT</code>), InvalidateBlock (<code>0x0000</code>), Wear-Leveling 4 Slots &amp; Wrap-Around <code>0xFF→0x00</code></td></tr><tr><td>Nhóm 3</td><td><b>S9 – S11</b></td><td>Immediate Crash + Pre-Erase, <code>Ea_SetMode(FAST/SLOW)</code>, Polling vs Callback Notification</td></tr><tr><td>Nhóm 4</td><td><b>S12 – S14</b></td><td><code>Ea_Cancel()</code>, Tiêm lỗi phần cứng DEM từ Eep, Full Test 6 mã lỗi DET &amp; Runtime Errors</td></tr></tbody></table><p style='margin-top:8px'>Mọi thay đổi trên cấu hình ECUC đều có thể xuất ngay ở nút <b>📦 Export</b> trên Header thành <code>Ea.arxml</code>, <code>Ea_Cfg.h</code>, <code>Ea_Lcfg.c</code>, hoặc <code>Ea_Config.json</code> — và tải toàn bộ Simulator về máy bằng nút <b>⬇ Tải .HTML</b>.</p></div>"
      }
    ]
  }
];
